ee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"catalog_kind":"function","schema":"public","owner":"postgres","body_md5":"17fee06fe96eaccd15d01d65b5f0ff69","definition_md5":"b15fb327f4dd6272f8555e051b0565bc","security_definer":true,"volatility":"v","configuration":["search_path=pg_catalog, public, extensions"]},{"object_kind":"view","object_identity":"public.v_admin_health_snapshot","restore_order":"850004","original_sha256":"c41722314d98f8466f7b17ae3e832daf8f2e04ffe21cf86f0de3ca7d4224533b","saved_sha256":"94727a754bb4ad6ebbe0d941370acd9ff730c2f1868c02630e948bccb6cecb58","current_sha256":"94727a754bb4ad6ebbe0d941370acd9ff730c2f1868c02630e948bccb6cecb58","current_definition_sql":"create or replace view public.v_admin_health_snapshot as  WITH cfg AS (\n         SELECT get_setting_int('stale_session_timeout_minutes'::text, 120) AS stale_timeout_minutes,\n            get_setting_int('scan_history_warning_mb'::text, 350) AS scan_history_warning_mb,\n            operational_day_start(now()) AS operational_day_start\n        ), storage AS (\n         SELECT scan_history_storage_summary() AS summary\n        ), counts AS (\n         SELECT ( SELECT count(*) AS count\n                   FROM custodial_open_work() custodial_open_work(open_work_id, source_kind, session_id, context_id, session_uuid, client_session_id, location_id, location_code, location_name, employee_id, employee_name, device_id, device_identifier, status, started_at, ended_at, duration_minutes, duration_display, created_at)\n                  WHERE custodial_open_work.status = 'active'::text) AS active_sessions,\n            ( SELECT count(*) AS count\n                   FROM custodial_open_work() custodial_open_work(open_work_id, source_kind, session_id, context_id, session_uuid, client_session_id, location_id, location_code, location_name, employee_id, employee_name, device_id, device_identifier, status, started_at, ended_at, duration_minutes, duration_display, created_at)\n                  WHERE custodial_open_work.status = 'pending_submit'::text) AS pending_submit_sessions,\n            ( SELECT count(*) AS count\n                   FROM sessions\n                  WHERE sessions.status = 'closed'::text AND COALESCE(sessions.ended_at, sessions.started_at, sessions.created_at) >= (( SELECT cfg.operational_day_start\n                           FROM cfg))) AS closed_sessions_today,\n            ( SELECT count(*) AS count\n                   FROM v_open_maintenance_tickets) AS open_ticket_count,\n            ( SELECT count(*) AS count\n                   FROM v_location_dashboard_status\n                  WHERE v_location_dashboard_status.status_code = 'overdue'::text) AS overdue_locations,\n            ( SELECT count(*) AS count\n                   FROM v_location_dashboard_status\n                  WHERE v_location_dashboard_status.status_code = 'due_soon'::text) AS due_soon_locations,\n            ( SELECT count(*) AS count\n                   FROM v_location_dashboard_status\n                  WHERE v_location_dashboard_status.status_code = 'in_progress'::text) AS in_progress_locations,\n            ( SELECT count(*) AS count\n                   FROM locations\n                  WHERE locations.active = true) AS active_locations,\n            ( SELECT count(*) AS count\n                   FROM devices\n                  WHERE devices.active = true) AS active_devices,\n            ( SELECT count(*) AS count\n                   FROM devices\n                  WHERE devices.active = true AND devices.last_seen_at >= (now() - '24:00:00'::interval)) AS devices_seen_last_24h,\n            ( SELECT count(*) AS count\n                   FROM devices\n                  WHERE devices.active = true AND (devices.last_seen_at IS NULL OR devices.last_seen_at < (now() - '24:00:00'::interval))) AS devices_missing_recent_heartbeat,\n            ( SELECT count(*) AS count\n                   FROM custodial_open_work() custodial_open_work(open_work_id, source_kind, session_id, context_id, session_uuid, client_session_id, location_id, location_code, location_name, employee_id, employee_name, device_id, device_identifier, status, started_at, ended_at, duration_minutes, duration_display, created_at)\n                  WHERE COALESCE(custodial_open_work.ended_at, custodial_open_work.started_at) <= (now() - make_interval(mins => ( SELECT cfg.stale_timeout_minutes\n                           FROM cfg)))) AS stale_open_sessions,\n            ( SELECT count(*) AS count\n                   FROM system_logs\n                  WHERE (system_logs.level = ANY (ARRAY['WARN'::text, 'ERROR'::text])) AND system_logs.created_at >= (now() - '24:00:00'::interval)) AS warn_error_logs_last_24h\n        )\n SELECT now() AS snapshot_at,\n    ( SELECT cfg.operational_day_start\n           FROM cfg) AS operational_day_start,\n    ( SELECT cfg.stale_timeout_minutes\n           FROM cfg) AS stale_timeout_minutes,\n    ( SELECT cfg.scan_history_warning_mb\n           FROM cfg) AS scan_history_warning_mb,\n    counts.active_sessions,\n    counts.pending_submit_sessions,\n    counts.closed_sessions_today,\n    counts.open_ticket_count,\n    counts.overdue_locations,\n    counts.due_soon_locations,\n    counts.in_progress_locations,\n    counts.active_locations,\n    counts.active_devices,\n    counts.devices_seen_last_24h,\n    counts.devices_missing_recent_heartbeat,\n    counts.stale_open_sessions,\n    counts.warn_error_logs_last_24h,\n    storage.summary AS storage_summary\n   FROM counts\n     CROSS JOIN storage; alter view public.v_admin_health_snapshot reset (check_option,security_barrier,security_invoker); alter view public.v_admin_health_snapshot owner to postgres;","classification":"view_terminal_owner_only","explicit_identity":"public.v_admin_health_snapshot","catalog_kind":"view","schema":"public","owner":"postgres","relation_kind":"v","relation_options":null},{"object_kind":"view","object_identity":"public.v_exception_queue","restore_order":"850005","original_sha256":"af8fcfd45b4b8392c51ffb73f5269a559c4c40c5321a93bcac67af02619e06b2","saved_sha256":"448695dcb7db375c283c1b18e8078a5a1b8ab0c79bb51222792dac183848a1fc","current_sha256":"448695dcb7db375c283c1b18e8078a5a1b8ab0c79bb51222792dac183848a1fc","current_definition_sql":"create or replace view public.v_exception_queue as  SELECT 'open_ticket'::text AS exception_type,\n    ticket.ticket_id::text AS entity_id,\n    ticket.location_code,\n    ticket.location_name,\n    ticket.date_submitted AS event_at,\n    ticket.date_submitted_display AS event_at_display,\n    ticket.maintenance_issue AS summary,\n    ticket.reported_by AS actor,\n    jsonb_build_object('fixture_type', ticket.fixture_type, 'fixture_identifier', ticket.fixture_identifier, 'out_of_order', ticket.out_of_order, 'status', ticket.status) AS details\n   FROM v_open_maintenance_tickets ticket\nUNION ALL\n SELECT 'overdue_location'::text AS exception_type,\n    location.location_id::text AS entity_id,\n    location.location_code,\n    location.location_name,\n    location.latest_completed_at AS event_at,\n    location.latest_completed_at_display AS event_at_display,\n    'Location overdue for cleaning'::text AS summary,\n    location.latest_employee_name AS actor,\n    jsonb_build_object('form_type', location.form_type, 'status_code', location.status_code, 'status_color', location.status_color, 'open_ticket_count', location.open_ticket_count) AS details\n   FROM v_location_dashboard_status location\n  WHERE location.status_code = 'overdue'::text\nUNION ALL\n SELECT 'stale_device'::text AS exception_type,\n    device.id::text AS entity_id,\n    NULL::text AS location_code,\n    device.device_name AS location_name,\n    GREATEST(device.last_seen_at, sync.last_server_ack_at, sync.updated_at) AS event_at,\n        CASE\n            WHEN GREATEST(device.last_seen_at, sync.last_server_ack_at, sync.updated_at) IS NULL THEN 'Never seen'::text\n            ELSE to_char(timezone('America/Chicago'::text, GREATEST(device.last_seen_at, sync.last_server_ack_at, sync.updated_at)), 'MM/DD/YYYY HH12:MI AM'::text) || ' Central'::text\n        END AS event_at_display,\n    'Device missing recent heartbeat'::text AS summary,\n    device.device_id AS actor,\n    jsonb_build_object('device_id', device.device_id, 'active', device.active, 'last_seen_at', device.last_seen_at, 'last_server_ack_at', sync.last_server_ack_at, 'sync_updated_at', sync.updated_at) AS details\n   FROM devices device\n     LEFT JOIN device_sync_status sync ON sync.device_id = device.id\n  WHERE device.active = true AND device.assigned_employee_id IS NOT NULL AND (GREATEST(device.last_seen_at, sync.last_server_ack_at, sync.updated_at) IS NULL OR GREATEST(device.last_seen_at, sync.last_server_ack_at, sync.updated_at) < (now() - '24:00:00'::interval))\nUNION ALL\n SELECT 'stale_open_session'::text AS exception_type,\n    work.session_uuid AS entity_id,\n    work.location_code,\n    work.location_name,\n    COALESCE(work.ended_at, work.started_at) AS event_at,\n    to_char(timezone('America/Chicago'::text, COALESCE(work.ended_at, work.started_at)), 'MM/DD/YYYY HH12:MI AM'::text) || ' Central'::text AS event_at_display,\n    'Open session exceeded stale timeout'::text AS summary,\n    work.employee_name AS actor,\n    jsonb_build_object('status', work.status, 'device_id', work.device_identifier, 'started_at', work.started_at, 'ended_at', work.ended_at) AS details\n   FROM custodial_open_work() work(open_work_id, source_kind, session_id, context_id, session_uuid, client_session_id, location_id, location_code, location_name, employee_id, employee_name, device_id, device_identifier, status, started_at, ended_at, duration_minutes, duration_display, created_at)\n  WHERE COALESCE(work.ended_at, work.started_at) <= (now() - make_interval(mins => get_setting_int('stale_session_timeout_minutes'::text, 120))); alter view public.v_exception_queue reset (check_option,security_barrier,security_invoker); alter view public.v_exception_queue owner to postgres;","classification":"view_terminal_owner_only","explicit_identity":"public.v_exception_queue","catalog_kind":"view","schema":"public","owner":"postgres","relation_kind":"v","relation_options":null},{"object_kind":"view","object_identity":"public.v_location_dashboard_status","restore_order":"850002","original_sha256":"01f2738d65fe42e4aa6c3af221cde19b7550c9ece1edd2654890a9ce52df24c5","saved_sha256":"7956b0b208e62458fdd54bf96578c06fc490d583e5fcf06aa66baa2cbe8957d9","current_sha256":"7956b0b208e62458fdd54bf96578c06fc490d583e5fcf06aa66baa2cbe8957d9","current_definition_sql":"create or replace view public.v_location_dashboard_status as  WITH op_day AS (\n         SELECT operational_day_start(now()) AS day_start,\n            sch_service_date(now()) AS service_date\n        ), authority AS (\n         SELECT state.service_date,\n            state.governed,\n            state.authority_source,\n            state.projection_status,\n            state.version_id,\n            state.publication_id,\n            state.projection_id,\n            state.projection_authority_revision,\n            state.staffing_authority_revision,\n            state.week_start\n           FROM op_day day\n             CROSS JOIN LATERAL static_weekly_v6_schedule_authority_state(day.service_date) state(service_date, governed, authority_source, projection_status, version_id, publication_id, projection_id, projection_authority_revision, staffing_authority_revision, week_start)\n        ), scheduled_baseline AS (\n         SELECT assignment.location_id,\n            min(((day.service_date + assignment.coverage_start) AT TIME ZONE 'America/Chicago'::text)) AS baseline_at\n           FROM op_day day\n             JOIN LATERAL custodial_operational_location_assignments(day.service_date) assignment(service_date, authority_source, projection_status, version_id, publication_id, projection_id, occurrence_id, location_group_id, group_code, group_name, assigned_employee_id, assigned_employee_name, assignment_status, coverage_start, coverage_end, location_id, location_code, location_name, form_type) ON true\n          GROUP BY assignment.location_id\n        ), latest_scan AS (\n         SELECT scan_events.location_id,\n            max(COALESCE(scan_events.scanned_at, scan_events.created_at)) AS last_scan_at\n           FROM scan_events\n          GROUP BY scan_events.location_id\n        ), open_session AS (\n         SELECT DISTINCT ON (work.location_id) work.location_id,\n            work.location_code,\n            work.session_id,\n            work.session_uuid,\n            work.status AS session_status,\n            work.started_at,\n            work.ended_at,\n            work.duration_minutes,\n            work.duration_display,\n            work.employee_name,\n            work.device_identifier\n           FROM custodial_open_work() work(open_work_id, source_kind, session_id, context_id, session_uuid, client_session_id, location_id, location_code, location_name, employee_id, employee_name, device_id, device_identifier, status, started_at, ended_at, duration_minutes, duration_display, created_at)\n          WHERE work.source_kind <> 'session'::text OR work.started_at >= operational_day_start(now())\n          ORDER BY work.location_id, work.started_at DESC, work.created_at DESC, work.open_work_id DESC\n        ), latest_completed AS (\n         SELECT DISTINCT ON (session.location_id) session.location_id,\n            session.id AS session_id,\n            session.session_uuid,\n            session.started_at,\n            session.ended_at,\n            session.duration_minutes,\n            session.duration_display,\n            employee.display_name AS employee_name,\n            completion.submitted_at,\n            completion.response_json,\n            COALESCE(session.ended_at, completion.submitted_at, session.started_at) AS effective_completed_at\n           FROM sessions session\n             JOIN employees employee ON employee.id = session.employee_id\n             LEFT JOIN completion_responses completion ON completion.session_id = session.id\n             CROSS JOIN op_day day\n          WHERE session.status = 'closed'::text AND (completion.response_json ->> 'work_result'::text) IS DISTINCT FROM 'checked_no_cleaning_needed'::text AND COALESCE(session.ended_at, completion.submitted_at, session.started_at) >= day.day_start\n          ORDER BY session.location_id, (COALESCE(session.ended_at, completion.submitted_at, session.started_at)) DESC, session.started_at DESC\n        ), open_tickets AS (\n         SELECT maintenance_tickets.location_id,\n            count(*) AS open_ticket_count\n           FROM maintenance_tickets\n          WHERE maintenance_tickets.status = 'open'::text\n          GROUP BY maintenance_tickets.location_id\n        ), truth AS (\n         SELECT location.id AS location_id,\n            COALESCE(open_session.location_code, location.location_code) AS location_code,\n            place_operational_location_name(location.id, statement_timestamp()) AS location_name,\n            location.location_type,\n            location.form_type,\n            day.day_start,\n            latest_scan.last_scan_at,\n            open_session.session_id AS open_session_id,\n            open_session.session_uuid AS open_session_uuid,\n            open_session.session_status AS open_session_status,\n            open_session.started_at AS open_session_started_at,\n            open_session.ended_at AS open_session_ended_at,\n            open_session.employee_name AS open_session_employee_name,\n            open_session.device_identifier AS open_session_device_identifier,\n            latest_completed.session_id AS latest_completed_session_id,\n            latest_completed.session_uuid AS latest_completed_session_uuid,\n            latest_completed.started_at AS latest_started_at,\n            latest_completed.ended_at AS latest_ended_at,\n            latest_completed.submitted_at AS latest_submitted_at,\n            latest_completed.effective_completed_at AS latest_completed_at,\n            latest_completed.employee_name AS latest_employee_name,\n            latest_completed.duration_minutes,\n            latest_completed.duration_display,\n            latest_completed.response_json,\n            COALESCE(open_tickets.open_ticket_count, 0::bigint) AS open_ticket_count,\n            scheduled_baseline.baseline_at,\n            mz_latest_verified_check(location.id, day.day_start, now()) AS verified_check_at,\n                CASE\n                    WHEN latest_completed.effective_completed_at IS NULL THEN NULL::timestamp with time zone\n                    ELSE GREATEST(latest_completed.effective_completed_at, mz_latest_verified_check(location.id, day.day_start, now()))\n                END AS due_baseline_at,\n            authority.authority_source AS schedule_authority_source,\n            authority.projection_status AS schedule_projection_status\n           FROM locations location\n             CROSS JOIN op_day day\n             CROSS JOIN authority\n             LEFT JOIN scheduled_baseline ON scheduled_baseline.location_id = location.id\n             LEFT JOIN latest_scan ON latest_scan.location_id = location.id\n             LEFT JOIN open_session ON open_session.location_id = location.id\n             LEFT JOIN latest_completed ON latest_completed.location_id = location.id\n             LEFT JOIN open_tickets ON open_tickets.location_id = location.id\n          WHERE location.active = true\n        )\n SELECT location_id,\n    location_code,\n    location_name,\n    location_type,\n    form_type,\n    day_start AS operational_day_start,\n    last_scan_at,\n    open_session_id,\n    open_session_uuid,\n    open_session_status,\n    open_session_started_at,\n    open_session_ended_at,\n    latest_completed_session_id,\n    latest_completed_session_uuid,\n    latest_started_at,\n    latest_ended_at,\n    latest_submitted_at,\n    latest_completed_at,\n    latest_employee_name,\n    duration_minutes,\n    duration_display,\n    COALESCE(response_json -> 'services_performed'::text, response_json -> 'servicesPerformed'::text, response_json -> 'services'::text, response_json -> 'completed_services'::text, response_json -> 'completedServices'::text, '[]'::jsonb) AS services_performed,\n    COALESCE(response_json ->> 'notes'::text, response_json ->> 'cleaning_notes'::text, response_json ->> 'cleaningNotes'::text, response_json ->> 'maintenance_notes'::text, response_json ->> 'maintenanceNotes'::text, response_json ->> 'other_service_performed'::text, response_json ->> 'otherServicePerformed'::text, response_json ->> 'note'::text) AS notes,\n    open_ticket_count,\n        CASE\n            WHEN due_baseline_at IS NULL AND (open_session_status = ANY (ARRAY['active'::text, 'pending_submit'::text])) THEN 'in_progress'::text\n            WHEN due_baseline_at IS NULL THEN 'not_cleaned'::text\n            WHEN form_type = 'restroom'::text AND now() >= (due_baseline_at + make_interval(mins =>\n            CASE\n                WHEN mz_is_approved_admin_location(location_id, now()) THEN 180\n                ELSE get_setting_int('restroom_overdue_minutes'::text, 90)\n            END)) THEN 'overdue'::text\n            WHEN form_type = 'restroom'::text AND now() >= (due_baseline_at + make_interval(mins =>\n            CASE\n                WHEN mz_is_approved_admin_location(location_id, now()) THEN 165\n                ELSE get_setting_int('restroom_due_soon_minutes'::text, 75)\n            END)) THEN 'due_soon'::text\n            WHEN form_type = 'exhibit'::text AND now() >= (due_baseline_at + make_interval(mins =>\n            CASE\n                WHEN mz_is_approved_admin_location(location_id, now()) THEN 180\n                ELSE get_setting_int('exhibit_overdue_minutes'::text, 210)\n            END)) THEN 'overdue'::text\n            WHEN form_type = 'exhibit'::text AND now() >= (due_baseline_at + make_interval(mins =>\n            CASE\n                WHEN mz_is_approved_admin_location(location_id, now()) THEN 165\n                ELSE get_setting_int('exhibit_due_soon_minutes'::text, 195)\n            END)) THEN 'due_soon'::text\n            WHEN open_session_status = ANY (ARRAY['active'::text, 'pending_submit'::text]) THEN 'in_progress'::text\n            ELSE 'okay'::text\n        END AS status_code,\n        CASE\n            WHEN due_baseline_at IS NULL AND (open_session_status = ANY (ARRAY['active'::text, 'pending_submit'::text])) THEN 'blue'::text\n            WHEN due_baseline_at IS NULL THEN 'black'::text\n            WHEN form_type = 'restroom'::text AND now() >= (due_baseline_at + make_interval(mins =>\n            CASE\n                WHEN mz_is_approved_admin_location(location_id, now()) THEN 180\n                ELSE get_setting_int('restroom_overdue_minutes'::text, 90)\n            END)) OR form_type = 'exhibit'::text AND now() >= (due_baseline_at + make_interval(mins =>\n            CASE\n                WHEN mz_is_approved_admin_location(location_id, now()) THEN 180\n                ELSE get_setting_int('exhibit_overdue_minutes'::text, 210)\n            END)) THEN 'red'::text\n            WHEN form_type = 'restroom'::text AND now() >= (due_baseline_at + make_interval(mins =>\n            CASE\n                WHEN mz_is_approved_admin_location(location_id, now()) THEN 165\n                ELSE get_setting_int('restroom_due_soon_minutes'::text, 75)\n            END)) OR form_type = 'exhibit'::text AND now() >= (due_baseline_at + make_interval(mins =>\n            CASE\n                WHEN mz_is_approved_admin_location(location_id, now()) THEN 165\n                ELSE get_setting_int('exhibit_due_soon_minutes'::text, 195)\n            END)) THEN 'yellow'::text\n            WHEN open_session_status = ANY (ARRAY['active'::text, 'pending_submit'::text]) THEN 'blue'::text\n            ELSE 'green'::text\n        END AS status_color,\n    to_char(timezone('America/Chicago'::text, day_start), 'MM/DD/YYYY HH12:MI AM'::text) || ' Central'::text AS operational_day_start_display,\n    to_char(timezone('America/Chicago'::text, last_scan_at), 'MM/DD/YYYY HH12:MI AM'::text) || ' Central'::text AS last_scan_at_display,\n    to_char(timezone('America/Chicago'::text, open_session_started_at), 'MM/DD/YYYY HH12:MI AM'::text) || ' Central'::text AS open_session_started_at_display,\n    to_char(timezone('America/Chicago'::text, open_session_ended_at), 'MM/DD/YYYY HH12:MI AM'::text) || ' Central'::text AS open_session_ended_at_display,\n    to_char(timezone('America/Chicago'::text, latest_started_at), 'MM/DD/YYYY HH12:MI AM'::text) || ' Central'::text AS latest_started_at_display,\n    to_char(timezone('America/Chicago'::text, latest_ended_at), 'MM/DD/YYYY HH12:MI AM'::text) || ' Central'::text AS latest_ended_at_display,\n    to_char(timezone('America/Chicago'::text, latest_submitted_at), 'MM/DD/YYYY HH12:MI AM'::text) || ' Central'::text AS latest_submitted_at_display,\n    to_char(timezone('America/Chicago'::text, latest_completed_at), 'MM/DD/YYYY HH12:MI AM'::text) || ' Central'::text AS latest_completed_at_display,\n    open_session_employee_name,\n    open_session_device_identifier,\n    schedule_authority_source,\n    schedule_projection_status,\n    GREATEST(latest_completed_at, verified_check_at) AS latest_checked_at\n   FROM truth; alter view public.v_location_dashboard_status reset (check_option,security_barrier,security_invoker); alter view public.v_location_dashboard_status owner to postgres;","classification":"view_terminal_owner_only","explicit_identity":"public.v_location_dashboard_status","catalog_kind":"view","schema":"public","owner":"postgres","relation_kind":"v","relation_options":null},{"object_kind":"view","object_identity":"public.v_location_status","restore_order":"850001","original_sha256":"4e58accd4dc4ea4c263ebc9076b9f7efc11252234329ebe499481c347718652c","saved_sha256":"6230595a44498b0c95ba596a61ec73372bb6b53990a650e408a9ced2e50f0c6f","current_sha256":"6230595a44498b0c95ba596a61ec73372bb6b53990a650e408a9ced2e50f0c6f","current_definition_sql":"create or replace view public.v_location_status as  WITH work_candidates AS (\n         SELECT work.location_id,\n            work.location_code,\n            work.session_id,\n            work.session_uuid,\n            work.status AS session_status,\n            work.started_at,\n            work.ended_at,\n            work.duration_minutes,\n            work.duration_display,\n            work.employee_name,\n            work.device_identifier AS device_id,\n            work.created_at,\n            0 AS source_priority\n           FROM custodial_open_work() work(open_work_id, source_kind, session_id, context_id, session_uuid, client_session_id, location_id, location_code, location_name, employee_id, employee_name, device_id, device_identifier, status, started_at, ended_at, duration_minutes, duration_display, created_at)\n          WHERE work.source_kind <> 'session'::text OR work.started_at >= operational_day_start(now())\n        UNION ALL\n         SELECT session.location_id,\n            NULL::text AS text,\n            session.id,\n            session.session_uuid,\n            session.status,\n            session.started_at,\n            session.ended_at,\n            session.duration_minutes,\n            session.duration_display,\n            employee.display_name,\n            device.device_id,\n            session.created_at,\n            1 AS source_priority\n           FROM sessions session\n             LEFT JOIN employees employee ON employee.id = session.employee_id\n             LEFT JOIN devices device ON device.id = session.device_id\n          WHERE session.status <> ALL (ARRAY['active'::text, 'pending_submit'::text])\n        ), ranked AS (\n         SELECT location.id AS location_id,\n            COALESCE(work.location_code, location.location_code) AS location_code,\n            location.location_name,\n            location.location_type,\n            location.active AS location_active,\n            work.session_id,\n            work.session_uuid,\n            work.session_status,\n            work.started_at,\n            work.ended_at,\n            work.duration_minutes,\n            work.duration_display,\n            work.employee_name,\n            work.device_id,\n            row_number() OVER (PARTITION BY location.id ORDER BY work.source_priority, work.started_at DESC NULLS LAST, work.created_at DESC NULLS LAST, work.session_id DESC NULLS LAST) AS rn\n           FROM locations location\n             LEFT JOIN work_candidates work ON work.location_id = location.id\n        )\n SELECT location_id,\n    location_code,\n    location_name,\n    location_type,\n    location_active,\n    session_id,\n    session_uuid,\n    session_status,\n    started_at,\n    ended_at,\n    duration_minutes,\n    duration_display,\n    employee_name,\n    device_id\n   FROM ranked\n  WHERE rn = 1; alter view public.v_location_status reset (check_option,security_barrier,security_invoker); alter view public.v_location_status owner to postgres;","classification":"view_terminal_owner_only","explicit_identity":"public.v_location_status","catalog_kind":"view","schema":"public","owner":"postgres","relation_kind":"v","relation_options":null},{"object_kind":"view","object_identity":"public.v_memphis_area_schedule","restore_order":"850009","original_sha256":"e13e853bf2653473553c62f20f286871393107509c11def746c9e371f2ddadd1","saved_sha256":"a472a46cf414c5e4095fc824826c76a3c84a7fa4ce041b9a9bf19194304f8219","current_sha256":"a472a46cf414c5e4095fc824826c76a3c84a7fa4ce041b9a9bf19194304f8219","current_definition_sql":"create or replace view public.v_memphis_area_schedule as  WITH authority_dates AS (\n         SELECT DISTINCT occurrence.service_date\n           FROM weekly_schedule_occurrences occurrence\n        UNION\n         SELECT DISTINCT assignment.service_date\n           FROM daily_schedule_assignments assignment\n        UNION\n         SELECT custodial_dated_service_dates.service_date\n           FROM custodial_dated_service_dates() custodial_dated_service_dates(service_date)\n        )\n SELECT segment.service_date,\n    segment.location_group_id,\n    segment.group_code,\n    segment.group_name,\n    segment.segment_number,\n    segment.assigned_employee_id,\n    segment.assigned_employee_name,\n    employee.employee_code,\n    \"left\"(segment.coverage_start, 5) AS coverage_start,\n    \"left\"(segment.coverage_end, 5) AS coverage_end,\n    segment.status,\n    segment.owner_type,\n    segment.load_points::numeric(10,2) AS load_points,\n    segment.source_type,\n    segment.notes\n   FROM authority_dates authority_date\n     CROSS JOIN LATERAL static_weekly_v6_read_schedule_segments(authority_date.service_date) segment(service_date, location_group_id, group_code, group_name, included_locations, included_location_ids, segment_id, segment_number, owner_type, assigned_employee_id, assigned_employee_name, coverage_start, coverage_end, status, load_points, coverage_purpose, notes, source_type, service_mode, governed, projection_status, version_id, publication_id, projection_id)\n     LEFT JOIN employees employee ON employee.id = segment.assigned_employee_id; alter view public.v_memphis_area_schedule reset (check_option,security_barrier,security_invoker); alter view public.v_memphis_area_schedule owner to postgres;","classification":"view_terminal_owner_only","explicit_identity":"public.v_memphis_area_schedule","catalog_kind":"view","schema":"public","owner":"postgres","relation_kind":"v","relation_options":null},{"object_kind":"view","object_identity":"public.v_open_maintenance_tickets","restore_order":"850000","original_sha256":"e3eb7ddcce97045100f13dfc88b7b042c4bdbebe9cc9c16f0e6d2ed2379d75cf","saved_sha256":"99935f49e16dd4fd80d5cc64629836a2d0d757bce799f5983a05d209b4e6eae8","current_sha256":"99935f49e16dd4fd80d5cc64629836a2d0d757bce799f5983a05d209b4e6eae8","current_definition_sql":"create or replace view public.v_open_maintenance_tickets as  SELECT mt.id AS ticket_id,\n    COALESCE(mt.location_code_snapshot, l.location_code) AS location_code,\n    COALESCE(mt.location_name_snapshot, l.location_name) AS location_name,\n    mt.reported_at AS date_submitted,\n    mt.issue_summary AS maintenance_issue,\n    COALESCE(mt.reporter_name_snapshot, e.display_name) AS reported_by,\n    mt.fixture_type,\n    mt.fixture_identifier,\n    mt.out_of_order,\n    mt.status,\n    mt.issue_payload,\n    mt.close_notes,\n    mt.created_at,\n    to_char(timezone('America/Chicago'::text, mt.reported_at), 'MM/DD/YYYY'::text) AS date_submitted_date_display,\n    to_char(timezone('America/Chicago'::text, mt.reported_at), 'MM/DD/YYYY HH12:MI AM'::text) || ' Central'::text AS date_submitted_display,\n    to_char(timezone('America/Chicago'::text, mt.created_at), 'MM/DD/YYYY HH12:MI AM'::text) || ' Central'::text AS created_at_display,\n    mt.issue_source\n   FROM maintenance_tickets mt\n     LEFT JOIN locations l ON l.id = mt.location_id\n     LEFT JOIN employees e ON e.id = mt.reported_by_employee_id\n  WHERE mt.status = 'open'::text; alter view public.v_open_maintenance_tickets reset (check_option,security_barrier,security_invoker); alter view public.v_open_maintenance_tickets owner to postgres;","classification":"view_terminal_owner_only","explicit_identity":"public.v_open_maintenance_tickets","catalog_kind":"view","schema":"public","owner":"postgres","relation_kind":"v","relation_options":null},{"object_kind":"view","object_identity":"public.v_restroom_check_timers","restore_order":"850003","original_sha256":"8dd302c13b6c138e49ebccb7fa548734d35d0d3bc64cf05c2ab3563b773b6fbd","saved_sha256":"7a3f322a4d0ac8c6dca8e34fd3fb693e81a43c4fd34a71b7713406cc43976b5d","current_sha256":"7a3f322a4d0ac8c6dca8e34fd3fb693e81a43c4fd34a71b7713406cc43976b5d","current_definition_sql":"create or replace view public.v_restroom_check_timers as  WITH restroom_locations AS (\n         SELECT group_row.id AS location_group_id,\n            group_row.group_code,\n            group_row.group_name,\n            location.id AS location_id,\n            location.location_code,\n            location.location_name\n           FROM location_groups group_row\n             JOIN location_group_memberships membership ON membership.location_group_id = group_row.id AND membership.active = true\n             JOIN locations location ON location.id = membership.location_id AND location.active = true\n          WHERE group_row.active = true AND lower(COALESCE(location.form_type, location.location_type, ''::text)) = 'restroom'::text AND sch_is_public_restroom_group(group_row.id) AND NOT (location.location_name ~~* '%East Admin%'::text OR location.location_name ~~* '%West Admin%'::text OR location.location_name ~~* '%Elephant Trunk%'::text)\n        ), activity AS (\n         SELECT session.location_id,\n            COALESCE(session.ended_at, completion.submitted_at, session.started_at) AS activity_at,\n            COALESCE(submitter.display_name, employee.display_name) AS actor_name,\n            COALESCE(completion_device.device_id, device.device_id) AS device_identifier\n           FROM sessions session\n             LEFT JOIN completion_responses completion ON completion.session_id = session.id\n             LEFT JOIN employees submitter ON submitter.id = completion.submitted_by_employee_id\n             LEFT JOIN employees employee ON employee.id = session.employee_id\n             LEFT JOIN devices completion_device ON completion_device.id = completion.device_id\n             LEFT JOIN devices device ON device.id = session.device_id\n          WHERE COALESCE(session.ended_at, completion.submitted_at, session.started_at) >= operational_day_start(now()) AND session.status = 'closed'::text AND ((completion.response_json ->> 'work_result'::text) IS DISTINCT FROM 'checked_no_cleaning_needed'::text OR session.ended_at = mz_latest_verified_check(session.location_id, operational_day_start(now()), now()))\n        ), latest_completion AS (\n         SELECT DISTINCT ON (restroom_1.location_id) restroom_1.location_id,\n            activity.activity_at AS last_completed_at,\n            activity.actor_name AS last_completed_by,\n            activity.device_identifier AS last_completed_device\n           FROM restroom_locations restroom_1\n             LEFT JOIN activity ON activity.location_id = restroom_1.location_id\n          ORDER BY restroom_1.location_id, activity.activity_at DESC NULLS LAST\n        ), current_owner AS (\n         SELECT DISTINCT ON (assignment.location_group_id) assignment.location_group_id,\n            assignment.assigned_employee_id,\n            employee.display_name AS assigned_owner,\n            assignment.coverage_start::time without time zone AS coverage_start,\n            assignment.coverage_end::time without time zone AS coverage_end,\n            assignment.coverage_purpose,\n            assignment.status\n           FROM static_weekly_v6_read_schedule_segments(sch_service_date(now())) assignment(service_date, location_group_id, group_code, group_name, included_locations, included_location_ids, segment_id, segment_number, owner_type, assigned_employee_id, assigned_employee_name, coverage_start, coverage_end, status, load_points, coverage_purpose, notes, source_type, service_mode, governed, projection_status, version_id, publication_id, projection_id)\n             LEFT JOIN employees employee ON employee.id = assignment.assigned_employee_id\n          WHERE assignment.service_date = sch_service_date(now()) AND timezone('America/Chicago'::text, now())::time without time zone >= assignment.coverage_start::time without time zone AND timezone('America/Chicago'::text, now())::time without time zone < assignment.coverage_end::time without time zone\n          ORDER BY assignment.location_group_id, (\n                CASE\n                    WHEN assignment.coverage_purpose = ANY (ARRAY['restroom_check'::text, 'restroom_upkeep'::text, 'area_owner'::text]) THEN 0\n                    ELSE 1\n                END), assignment.coverage_start DESC\n        )\n SELECT sch_service_date(now()) AS service_date,\n    restroom.location_group_id,\n    restroom.group_code,\n    restroom.group_name AS schedule_package_name,\n    restroom.location_id,\n    restroom.location_code,\n    restroom.location_name AS scanned_restroom_name,\n    latest.last_completed_at,\n    timezone('America/Chicago'::text, latest.last_completed_at) AS last_completed_at_central,\n    latest.last_completed_by,\n    latest.last_completed_device,\n        CASE\n            WHEN dashboard.latest_completed_at IS NOT NULL AND latest.last_completed_at IS NOT NULL THEN latest.last_completed_at + '01:30:00'::interval\n            ELSE NULL::timestamp with time zone\n        END AS next_check_due_at,\n        CASE\n            WHEN dashboard.latest_completed_at IS NOT NULL AND latest.last_completed_at IS NOT NULL THEN timezone('America/Chicago'::text, latest.last_completed_at + '01:30:00'::interval)\n            ELSE NULL::timestamp without time zone\n        END AS next_check_due_at_central,\n        CASE\n            WHEN dashboard.latest_completed_at IS NULL OR latest.last_completed_at IS NULL THEN 'not_cleaned_yet'::text\n            WHEN (latest.last_completed_at + '01:30:00'::interval) <= now() THEN 'overdue'::text\n            WHEN (latest.last_completed_at + '01:30:00'::interval) <= (now() + '00:15:00'::interval) THEN 'due_soon'::text\n            ELSE 'ok'::text\n        END AS timer_status,\n        CASE\n            WHEN dashboard.latest_completed_at IS NOT NULL AND latest.last_completed_at IS NOT NULL THEN round(EXTRACT(epoch FROM latest.last_completed_at + '01:30:00'::interval - now()) / 60.0)::integer\n            ELSE NULL::integer\n        END AS minutes_until_due,\n    owner.assigned_employee_id,\n    owner.assigned_owner,\n    to_char(owner.coverage_start::interval, 'HH24:MI'::text) AS owner_coverage_start,\n    to_char(owner.coverage_end::interval, 'HH24:MI'::text) AS owner_coverage_end,\n    owner.coverage_purpose,\n    owner.status AS owner_status,\n        CASE\n            WHEN dashboard.latest_completed_at IS NOT NULL AND latest.last_completed_at IS NOT NULL THEN 'scan_completion'::text\n            ELSE 'no_scan_today'::text\n        END AS timer_source\n   FROM restroom_locations restroom\n     LEFT JOIN v_location_dashboard_status dashboard ON dashboard.location_id = restroom.location_id\n     LEFT JOIN latest_completion latest ON latest.location_id = restroom.location_id\n     LEFT JOIN current_owner owner ON owner.location_group_id = restroom.location_group_id; alter view public.v_restroom_check_timers reset (check_option,security_barrier,security_invoker); alter view public.v_restroom_check_timers owner to postgres;","classification":"view_terminal_owner_only","explicit_identity":"public.v_restroom_check_timers","catalog_kind":"view","schema":"public","owner":"postgres","relation_kind":"v","relation_options":null},{"object_kind":"view","object_identity":"public.v_restroom_package_status","restore_order":"850006","original_sha256":"2fe5b2142c577937fe58b385d3f34ed5e2102026066c782ced0d1c1ac5a81065","saved_sha256":"82d51cc69fc3e048e4d29e515805ee25415a3828b8095e58be5236bc1a110a10","current_sha256":"82d51cc69fc3e048e4d29e515805ee25415a3828b8095e58be5236bc1a110a10","current_definition_sql":"create or replace view public.v_restroom_package_status as  SELECT service_date,\n    location_group_id,\n    group_code,\n    schedule_package_name,\n    count(*)::integer AS restroom_count,\n    count(*) FILTER (WHERE timer_status <> 'not_cleaned_yet'::text)::integer AS cleaned_count,\n    count(*) FILTER (WHERE timer_status = 'not_cleaned_yet'::text)::integer AS not_cleaned_count,\n    count(*) FILTER (WHERE timer_status = 'due_soon'::text)::integer AS due_soon_count,\n    count(*) FILTER (WHERE timer_status = 'overdue'::text)::integer AS overdue_count,\n    min(next_check_due_at) FILTER (WHERE next_check_due_at IS NOT NULL) AS next_package_due_at,\n    min(next_check_due_at_central) FILTER (WHERE next_check_due_at_central IS NOT NULL) AS next_package_due_at_central,\n    assigned_employee_id,\n    assigned_owner,\n    owner_coverage_start,\n    owner_coverage_end,\n        CASE\n            WHEN count(*) FILTER (WHERE timer_status = 'overdue'::text) > 0 THEN 'overdue'::text\n            WHEN count(*) FILTER (WHERE timer_status = 'due_soon'::text) > 0 THEN 'due_soon'::text\n            WHEN count(*) FILTER (WHERE timer_status = 'not_cleaned_yet'::text) = count(*) THEN 'not_cleaned_yet'::text\n            WHEN count(*) FILTER (WHERE timer_status = 'not_cleaned_yet'::text) > 0 THEN 'partially_cleaned'::text\n            ELSE 'ok'::text\n        END AS package_status\n   FROM v_restroom_check_timers\n  GROUP BY service_date, location_group_id, group_code, schedule_package_name, assigned_employee_id, assigned_owner, owner_coverage_start, owner_coverage_end; alter view public.v_restroom_package_status reset (check_option,security_barrier,security_invoker); alter view public.v_restroom_package_status owner to postgres;","classification":"view_terminal_owner_only","explicit_identity":"public.v_restroom_package_status","catalog_kind":"view","schema":"public","owner":"postgres","relation_kind":"v","relation_options":null},{"object_kind":"view","object_identity":"public.v_weekly_schedule_effective_ranges","restore_order":"850008","original_sha256":"fe59fb80eed78f0dcbed3f5fcb713e737ca55d997e735a7d91009b955003787d","saved_sha256":"5229a9ef7b214e833ee92ae2f56be3c31d7c8bee311b6b83771b74369649aabe","current_sha256":"5229a9ef7b214e833ee92ae2f56be3c31d7c8bee311b6b83771b74369649aabe","current_definition_sql":"create or replace view public.v_weekly_schedule_effective_ranges as  WITH winners AS (\n         SELECT DISTINCT ON (p.effective_start) v.version_id,\n            v.version_number,\n            p.effective_start,\n            v.publication_kind,\n            v.content_digest\n           FROM weekly_schedule_publications p\n             JOIN weekly_schedule_versions v ON v.version_id = p.version_id\n          WHERE v.lifecycle_state = 'published'::text\n          ORDER BY p.effective_start, p.authority_revision DESC\n        )\n SELECT version_id,\n    version_number,\n    effective_start,\n    lead(effective_start) OVER (ORDER BY effective_start) AS effective_end,\n    publication_kind,\n    content_digest\n   FROM winners; alter view public.v_weekly_schedule_effective_ranges reset (check_option,security_barrier,security_invoker); alter view public.v_weekly_schedule_effective_ranges owner to postgres;","classification":"view_terminal_owner_only","explicit_identity":"public.v_weekly_schedule_effective_ranges","catalog_kind":"view","schema":"public","owner":"postgres","relation_kind":"v","relation_options":null}],"repairs":[{"object_kind":"function","object_identity":"static_weekly_v5_read_employee_day(date,uuid,timestamp with time zone)","restore_order":"100187","preimage_sha256":"5f52ad4815a4edf7a6a3d65987f7f149b3329006e503361afa517bc927d9b917","replacement_sql":"CREATE OR REPLACE FUNCTION public.static_weekly_v5_read_employee_day(p_service_date date, p_employee_id uuid, p_now timestamp with time zone DEFAULT now())\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public'\nAS $function$\ndeclare rec jsonb:=public.custodial_dated_record(p_service_date);day jsonb;roster jsonb;items jsonb;loans jsonb;working boolean;current_items jsonb;phase text;\nbegin\n if rec is null then return public.static_weekly_v5_read_employee_day_dated_base(p_service_date,p_employee_id,p_now);end if;\n select d into day from jsonb_array_elements(rec->'days') d where d->>'serviceDate'=p_service_date::text;\n select r into roster from jsonb_array_elements(public.custodial_dated_rows('roster',p_service_date)) r where r->>'employee_id'=p_employee_id::text;\n if rec->>'projectionStatus'<>'current' or roster is null then\n  return jsonb_build_object('governed',true,'source','static_weekly_projection','projection_status',\n   case when roster is null then 'employee_not_in_dated_roster' else rec->>'projectionStatus' end,\n   'service_date',p_service_date,'employee_id',p_employee_id,'publication_id',rec->>'publicationId','projection_id',rec->>'projectionId');end if;\n working:=roster->>'active'='true';\n select coalesce(jsonb_agg(s||jsonb_build_object('id',s->>'segment_id','occurrence_id',s->>'segment_id',\n  'name',s->>'group_name','location_group_name',s->>'group_name','location_group_code',s->>'group_code',\n  'start_time',s->>'coverage_start','end_time',s->>'coverage_end','included_location_snapshots',o.assignment#>'{workSnapshot,includedLocations}') order by s->>'coverage_start',s->>'segment_id'),'[]') into items\n from jsonb_array_elements(public.custodial_dated_rows('segments',p_service_date)) s\n join public.custodial_dated_occurrences o on o.occurrence_id::text=s->>'segment_id'\n where s->>'assigned_employee_id'=p_employee_id::text;\n select coalesce(jsonb_agg(l||jsonb_build_object('id',(l->>'responsibility_id')||':'||(l->>'normal_occurrence_id'),\n  'occurrence_id',l->>'normal_occurrence_id','service_date',p_service_date,\n  'name',l->>'group_name','location_group_name',l->>'group_name','location_group_code',l->>'group_code',\n  'normal_owner_person_id',l->>'normal_owner_id','coverer_person_id',l->>'coverer_id',\n  'start_time',l->>'coverage_start','end_time',l->>'coverage_end',\n  'source_type','static_weekly_lunch_coverage','owner_type','EMPLOYEE',\n  'purpose','lunch_coverage','section_title','Lunch coverage','coverage_purpose','lunch_coverage',\n  'status','ASSIGNED','included_location_snapshots',l->'included_snapshots',\n  'on_call_only',coalesce(r->>'responseMode'='on_call_issues_only',false),\n  'normal_owner_name',(select person->>'displayName' from jsonb_array_elements(rec#>'{plan,rosterSlots}') person where person->>'personId'=l->>'normal_owner_id'),\n  'check_deadline_policy',coalesce(r->>'checkDeadlinePolicy','inherit_existing_90_minute_deadline'),\n  'response_mode',r->>'responseMode','instruction',r->>'instruction','creates_deep_clean',false)\n  order by l->>'coverage_start',l->>'responsibility_id'),'[]') into loans\n from jsonb_array_elements(public.custodial_dated_rows('lunch',p_service_date)) l\n join lateral(select responsibility r from jsonb_array_elements(day->'lunchLoans') loan\n  cross join lateral jsonb_array_elements(loan->'responsibilities') responsibility\n  where responsibility->>'responsibilityId'=l->>'responsibility_id') rr on true\n where l->>'coverer_id'=p_employee_id::text;\n items:=items||loans;\n select coalesce(jsonb_agg(x),'[]') into current_items from jsonb_array_elements(items) x\n  where (p_now at time zone 'America/Chicago')::date=p_service_date\n  and (x->>'coverage_start')::time<=(p_now at time zone 'America/Chicago')::time\n  and (p_now at time zone 'America/Chicago')::time<(x->>'coverage_end')::time;\n phase:=case when not working then 'off_day' when (p_now at time zone 'America/Chicago')::date<p_service_date or ((p_now at time zone 'America/Chicago')::date=p_service_date and (p_now at time zone 'America/Chicago')::time<(roster->>'shift_start')::time) then 'before_shift'\n  when (p_now at time zone 'America/Chicago')::date>p_service_date or ((p_now at time zone 'America/Chicago')::date=p_service_date and (p_now at time zone 'America/Chicago')::time>=(roster->>'shift_end')::time) then 'after_shift' else 'assigned_areas' end;\n return jsonb_build_object('contract_version','static-weekly-employee-day.v3',\n  'governed',true,'source','static_weekly_projection','authority_scope','dated_transition',\n  'projection_status','current','service_date',p_service_date,'employee_id',p_employee_id,'employee_name',roster->>'employee_name',\n  'employee',jsonb_build_object('id',p_employee_id,'display_name',roster->>'employee_name'),\n  'version_id',day->>'weeklyVersionId','publication_id',rec->>'publicationId','projection_id',rec->>'projectionId',\n  'candidate_revision',rec->>'phonePdfRevision','authority_revision',rec->'revision','phase',phase,\n  'schedule_status',case when working then 'scheduled' else 'off' end,\n  'shift',jsonb_build_object('active',working,'start',roster->>'shift_start','end',roster->>'shift_end'),\n  'all_items',items,'current_items',current_items,'items',current_items,\n  'assignment_count',jsonb_array_length(items),'lunch_coverage_contract','static-weekly-lunch-consumers.v1','lunch_coverage_status','PERSISTED');\nend $function$\n","replacement_sha256":"45b9a0701c2935ea93914d5652d711c5b814f8728af7f0b0575bf22531c32d2f"},{"object_kind":"grant","object_identity":"static_weekly_v5_read_employee_day(date,uuid,timestamp with time zone)","restore_order":"950009","preimage_sha256":"048274d946755c1ae04a485257f8b16653e515d9a14aa46dffeaf482f2a6c8ce","replacement_sql":"select public.custodial_release_authority_reset_grants('static_weekly_v5_read_employee_day(date,uuid,timestamp with time zone)'); grant execute on function static_weekly_v5_read_employee_day(date,uuid,timestamp with time zone) to service_role; grant execute on function static_weekly_v5_read_employee_day(date,uuid,timestamp with time zone) to custodial_application_reader;","replacement_sha256":"15c9a6a60b821065f4e36a1da987057991f428b3224a3f11d61c19e9f831c5db"}],"new_grants":false,"revocations":false,"owner_swaps":false,"business_row_writes":false,"production_execution_authorized":false,"candidate_migration_admission":false,"original_catalog_sha256":"56ad84f0e162aeda7ed0fbd033c623a7f20868fb83032fb916205af425e12dbd"}$existing_profile_json$::jsonb);
CREATE TEMP TABLE private_custody_existing_inventory_before ON COMMIT DROP AS
 SELECT * FROM public.custodial_release_authority_restore_inventory;
CREATE TEMP TABLE private_custody_existing_catalog_before(
 object_kind text,object_identity text,catalog jsonb,PRIMARY KEY(object_kind,object_identity)) ON COMMIT DROP;
DO $existing_profile$
DECLARE spec jsonb; item jsonb; repair jsonb; pass integer; obj oid; namespace text;
 actual jsonb; expected jsonb; named_acl jsonb; effective jsonb; column_acl jsonb;
 definition text; digest text; changed integer; expected_digest text;
BEGIN
 SELECT data INTO STRICT spec FROM private_custody_existing_profile;
 IF current_user<>'postgres' OR session_user<>current_user
  OR current_setting('custodial.deployment_project_ref',true) IS DISTINCT FROM 'rqquvtjdmugpigbndmne'
  OR current_setting('session_replication_role')<>'origin'
  OR current_setting('standard_conforming_strings')<>'on'
  OR NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname=current_user AND NOT rolsuper AND rolbypassrls)
  OR NOT EXISTS(SELECT 1 FROM pg_class WHERE oid='public.custodial_release_authority_restore_inventory'::regclass AND relowner='postgres'::regrole)
  OR NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.custodial_release_authority_restore_inventory'::regclass
   AND tgname='trg_custodial_release_authority_restore_inventory_immutable' AND tgenabled='A' AND NOT tgisinternal
   AND tgfoid='public.custodial_reject_release_authority_inventory_mutation()'::regprocedure)
  OR NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid='public.static_weekly_digest_text(text)'::regprocedure
   AND proowner='postgres'::regrole AND md5(pg_get_functiondef(oid))='19c60f10df9cca4c58e7d7f8b4a69e8d')
  OR NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid='public.custodial_release_authority_current_grant_definition(text)'::regprocedure
   AND proowner='postgres'::regrole AND md5(pg_get_functiondef(oid))='a1071b529d6ae4bd747b7a4195b90a6d')
  OR NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid='public.custodial_release_authority_current_view_definition(text)'::regprocedure
   AND proowner='postgres'::regrole AND md5(pg_get_functiondef(oid))='ee5410dc5313b8d21bc7abc537d503ae')
  OR spec->>'schema'<>'custodial.source252-existing-original-postgres.v1'
  OR spec->>'scope'<>'DISTINCT_EXISTING_RUNTIME_PROFILE_NOT_NOAUTO_EQUIVALENCE'
  OR jsonb_array_length(spec->'original_rows')<>6884 OR jsonb_array_length(spec->'exceptions')<>793
  OR jsonb_array_length(spec->'repairs')<>2
  OR spec->>'original_aggregate_sha256'<>'d9abaf120c47e789c6b3114717f14eb76d1ceacf9aea5600bccfb1005a176d27'
 THEN RAISE EXCEPTION 'Distinct existing Source252 actor/reference/ALWAYS guard changed';END IF;
 SELECT public.static_weekly_digest_text(string_agg((x->>2)||E'\n'||(x->>0)||E'\n'||(x->>1)||E'\n'||(x->>3),E'\n---\n'
  ORDER BY (x->>0) COLLATE "C",(x->>1) COLLATE "C")) INTO digest FROM jsonb_array_elements(spec->'original_rows') x;
 IF digest IS DISTINCT FROM spec->>'original_aggregate_sha256'
  OR (SELECT count(DISTINCT (x->>0,x->>1)) FROM jsonb_array_elements(spec->'original_rows') x)<>6884
  OR (SELECT count(DISTINCT (x->>'object_kind',x->>'object_identity')) FROM jsonb_array_elements(spec->'exceptions') x)<>793
 THEN RAISE EXCEPTION 'Distinct existing Source252 complete original reference changed';END IF;
 FOR pass IN 0..1 LOOP
  -- Complete original identity/order census, with only the finite independently
  -- reconstructed 793 preimages and the two declared metadata replacements.
  IF (SELECT count(*) FROM public.custodial_release_authority_restore_inventory)<>6884
   OR EXISTS(
    WITH original AS(SELECT x->>0 kind,x->>1 identity,(x->>2)::integer restore_order,x->>3 digest FROM jsonb_array_elements(spec->'original_rows') x),
    exceptions AS(SELECT x->>'object_kind' kind,x->>'object_identity' identity,x->>'saved_sha256' digest FROM jsonb_array_elements(spec->'exceptions') x),
    repairs AS(SELECT x->>'object_kind' kind,x->>'object_identity' identity,x->>'replacement_sha256' digest FROM jsonb_array_elements(spec->'repairs') x),
    wanted AS(SELECT o.kind,o.identity,o.restore_order,CASE WHEN pass=1 THEN coalesce(r.digest,e.digest,o.digest) ELSE coalesce(e.digest,o.digest) END digest
     FROM original o LEFT JOIN exceptions e USING(kind,identity) LEFT JOIN repairs r USING(kind,identity))
    SELECT 1 FROM wanted w FULL JOIN public.custodial_release_authority_restore_inventory i ON w.kind=i.object_kind AND w.identity=i.object_identity
    WHERE w.kind IS NULL OR i.object_kind IS NULL OR w.restore_order IS DISTINCT FROM i.restore_order
     OR w.digest IS DISTINCT FROM i.definition_sha256 OR i.definition_sha256 IS DISTINCT FROM public.static_weekly_digest_text(i.definition_sql))
  THEN RAISE EXCEPTION 'Distinct existing Source252 complete 6884 tuple/preimage census changed';END IF;
  expected_digest:=CASE WHEN pass=0 THEN spec->>'preimage_aggregate_sha256' ELSE spec->>'post_repair_aggregate_sha256' END;
  SELECT public.static_weekly_digest_text(string_agg(restore_order::text||E'\n'||object_kind||E'\n'||object_identity||E'\n'||definition_sha256,E'\n---\n'
   ORDER BY object_kind COLLATE "C",object_identity COLLATE "C")) INTO digest FROM public.custodial_release_authority_restore_inventory;
  IF digest IS DISTINCT FROM expected_digest THEN RAISE EXCEPTION 'Distinct existing Source252 finite profile aggregate changed';END IF;
  FOR item IN SELECT x FROM jsonb_array_elements(spec->'exceptions') x LOOP
   obj:=NULL;named_acl:=NULL;effective:=NULL;column_acl:=NULL;definition:=NULL;
   IF item->>'catalog_kind'='function' THEN
    obj:=to_regprocedure(item->>'explicit_identity');
    IF obj IS NULL OR to_regprocedure(item->>'object_identity')::oid IS DISTINCT FROM obj THEN
     RAISE EXCEPTION 'Distinct existing Source252 fixed routine public/namespace binding changed';END IF;
    SELECT n.nspname,jsonb_build_object('schema',n.nspname,'owner',pg_get_userbyid(p.proowner),'body_md5',md5(p.prosrc),
     'definition_md5',md5(pg_get_functiondef(p.oid)),'security_definer',p.prosecdef,'volatility',p.provolatile,'configuration',p.proconfig)
     INTO namespace,actual FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE p.oid=obj;
    expected:=jsonb_build_object('schema',item->'schema','owner',item->'owner','body_md5',item->'body_md5',
     'definition_md5',item->'definition_md5','security_definer',item->'security_definer','volatility',item->'volatility','configuration',item->'configuration');
    SELECT coalesce(jsonb_agg(jsonb_build_object('grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,
     'grantor',pg_get_userbyid(a.grantor),'privilege',a.privilege_type,'grantable',a.is_grantable)
     ORDER BY (CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END)::text COLLATE pg_catalog."C",pg_get_userbyid(a.grantor)::text COLLATE pg_catalog."C",a.privilege_type COLLATE pg_catalog."C",a.is_grantable),'[]'::jsonb)
     INTO named_acl FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE p.oid=obj;
    SELECT jsonb_object_agg(role,has_function_privilege(role,obj,'EXECUTE')) INTO effective
     FROM unnest(ARRAY['postgres','anon','authenticated','service_role','custodial_application_reader','static_weekly_control_plane','static_weekly_release_operator']) role;
    definition:=CASE WHEN item->>'object_kind'='function' THEN pg_get_functiondef(obj)
     ELSE public.custodial_release_authority_current_grant_definition(item->>'object_identity') END;
   ELSE
    obj:=to_regclass(item->>'explicit_identity');
    IF obj IS NULL OR to_regclass(item->>'object_identity')::oid IS DISTINCT FROM obj THEN
     RAISE EXCEPTION 'Distinct existing Source252 fixed relation binding changed';END IF;
    SELECT n.nspname,jsonb_build_object('schema',n.nspname,'owner',pg_get_userbyid(c.relowner),'relation_kind',c.relkind,'relation_options',c.reloptions,
     'row_security',c.relrowsecurity,'force_row_security',c.relforcerowsecurity)
     INTO namespace,actual FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.oid=obj;
    expected:=jsonb_build_object('schema',item->'schema','owner',item->'owner','relation_kind',item->'relation_kind','relation_options',item->'relation_options',
     'row_security',item->'row_security','force_row_security',item->'force_row_security');
    IF item->>'catalog_kind'='view' THEN actual:=actual-'row_security'-'force_row_security';expected:=expected-'row_security'-'force_row_security';END IF;
    SELECT coalesce(jsonb_agg(jsonb_build_object('grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,
     'grantor',pg_get_userbyid(a.grantor),'privilege',a.privilege_type,'grantable',a.is_grantable)
     ORDER BY (CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END)::text COLLATE pg_catalog."C",pg_get_userbyid(a.grantor)::text COLLATE pg_catalog."C",a.privilege_type COLLATE pg_catalog."C",a.is_grantable),'[]'::jsonb)
     INTO named_acl FROM pg_class c CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a WHERE c.oid=obj;
    SELECT jsonb_object_agg(role,(SELECT jsonb_object_agg(privilege,has_table_privilege(role,obj,privilege))
     FROM (SELECT DISTINCT privilege_type privilege FROM pg_class c CROSS JOIN LATERAL aclexplode(acldefault('r',c.relowner)) a WHERE c.oid=obj) rights))
     INTO effective FROM unnest(ARRAY['postgres','anon','authenticated','service_role','custodial_application_reader','static_weekly_control_plane','static_weekly_release_operator']) role;
    SELECT coalesce(jsonb_agg(jsonb_build_object('number',attnum,'name',attname,'acl',attacl::text) ORDER BY attnum),'[]'::jsonb)
     INTO column_acl FROM pg_attribute WHERE attrelid=obj AND attnum>0 AND NOT attisdropped;
    definition:=CASE WHEN item->>'object_kind'='view' THEN public.custodial_release_authority_current_view_definition(item->>'object_identity')
     ELSE public.custodial_release_authority_current_grant_definition(item->>'object_identity') END;
   END IF;
   IF actual IS DISTINCT FROM expected OR namespace IS DISTINCT FROM item->>'schema'
    OR definition IS DISTINCT FROM item->>'current_definition_sql'
    OR public.static_weekly_digest_text(definition) IS DISTINCT FROM item->>'current_sha256'
    OR (item ? 'acl' AND named_acl IS DISTINCT FROM (SELECT coalesce(jsonb_agg(x ORDER BY (x->>'grantee') COLLATE pg_catalog."C",(x->>'grantor') COLLATE pg_catalog."C",(x->>'privilege') COLLATE pg_catalog."C",(x->>'grantable')::boolean),'[]'::jsonb) FROM jsonb_array_elements(item->'acl') x))
   THEN RAISE EXCEPTION 'Distinct existing Source252 exact current body/owner/options/named privilege profile changed';END IF;
   actual:=jsonb_build_object('object_oid',obj,'catalog',actual,'acl',named_acl,'column_acl',column_acl,'effective',effective,'definition_sha256',public.static_weekly_digest_text(definition));
   IF pass=0 THEN
    INSERT INTO private_custody_existing_catalog_before VALUES(item->>'object_kind',item->>'object_identity',actual);
   ELSIF NOT EXISTS(SELECT 1 FROM private_custody_existing_catalog_before old WHERE old.object_kind=item->>'object_kind' AND old.object_identity=item->>'object_identity' AND old.catalog=actual) THEN
    RAISE EXCEPTION 'Distinct existing Source252 metadata-only repair changed existing catalog/effective privileges';
   END IF;
  END LOOP;
  IF pass=0 THEN
   -- Only these two obsolete recovery records change. Current routine bodies,
   -- named direct/column/effective ACLs, owners and all business rows stay put.
   ALTER TABLE public.custodial_release_authority_restore_inventory DISABLE TRIGGER trg_custodial_release_authority_restore_inventory_immutable;
   FOR repair IN SELECT x FROM jsonb_array_elements(spec->'repairs') x LOOP
    UPDATE public.custodial_release_authority_restore_inventory SET definition_sql=repair->>'replacement_sql',
     definition_sha256=repair->>'replacement_sha256',captured_at=statement_timestamp()
     WHERE object_kind=repair->>'object_kind' AND object_identity=repair->>'object_identity'
      AND restore_order=(repair->>'restore_order')::integer AND definition_sha256=repair->>'preimage_sha256'
      AND public.static_weekly_digest_text(definition_sql)=repair->>'preimage_sha256';
    GET DIAGNOSTICS changed=ROW_COUNT;
    IF changed<>1 OR public.static_weekly_digest_text(repair->>'replacement_sql') IS DISTINCT FROM repair->>'replacement_sha256' THEN
     RAISE EXCEPTION 'Distinct existing Source252 two-record exact preimage repair changed';END IF;
   END LOOP;
   ALTER TABLE public.custodial_release_authority_restore_inventory ENABLE ALWAYS TRIGGER trg_custodial_release_authority_restore_inventory_immutable;
  END IF;
 END LOOP;
 IF EXISTS(SELECT old.* FROM private_custody_existing_inventory_before old
   WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(spec->'repairs') r WHERE r->>'object_kind'=old.object_kind AND r->>'object_identity'=old.object_identity)
   EXCEPT SELECT now.* FROM public.custodial_release_authority_restore_inventory now)
  OR EXISTS(SELECT now.* FROM public.custodial_release_authority_restore_inventory now
   WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(spec->'repairs') r WHERE r->>'object_kind'=now.object_kind AND r->>'object_identity'=now.object_identity)
   EXCEPT SELECT old.* FROM private_custody_existing_inventory_before old)
  OR EXISTS(SELECT 1 FROM private_custody_existing_inventory_before old JOIN public.custodial_release_authority_restore_inventory now
   USING(object_kind,object_identity) WHERE (to_jsonb(old)-ARRAY['definition_sql','definition_sha256','captured_at'])
    IS DISTINCT FROM (to_jsonb(now)-ARRAY['definition_sql','definition_sha256','captured_at']))
 THEN RAISE EXCEPTION 'Distinct existing Source252 unrelated recovery metadata changed';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.custodial_release_authority_restore_inventory'::regclass
  AND tgname='trg_custodial_release_authority_restore_inventory_immutable' AND tgenabled='A'
  AND tgfoid='public.custodial_reject_release_authority_inventory_mutation()'::regprocedure) THEN
  RAISE EXCEPTION 'Distinct existing Source252 final ALWAYS inventory guard changed';END IF;
END $existing_profile$;
-- END DISTINCT EXISTING ORIGINAL-POSTGRES SOURCE252 PROFILE
CREATE TEMP TABLE private_custody_inventory_before ON COMMIT DROP AS
 SELECT * FROM public.custodial_release_authority_restore_inventory;
CREATE TEMP TABLE private_custody_surface_before ON COMMIT DROP AS
 SELECT p.proacl acl,p.proowner owner,pg_get_functiondef(p.oid) definition FROM pg_proc p
 WHERE p.oid='public.custodial_release_canary_authority_surface()'::regprocedure;
DO $private_predecessor$ DECLARE body text;saved public.custodial_release_authority_restore_inventory%rowtype;BEGIN
 SELECT definition INTO STRICT body FROM private_custody_surface_before;
 IF (SELECT count(*) FROM private_custody_inventory_before)<>6884
  OR public.static_weekly_digest_text(body) IS DISTINCT FROM 'd87c2c10574dbcaf542245a83b8019e66017b819a0abcc54d313074f831afb84'
  OR (length(body)-length(replace(body,'  values','')))/length('  values')<>1
  OR (SELECT public.static_weekly_digest_text(string_agg(restore_order::text||E'\n'||object_kind||E'\n'||object_identity||E'\n'||definition_sha256,E'\n---\n'
   ORDER BY object_kind COLLATE "C",object_identity COLLATE "C")) FROM private_custody_inventory_before)
   IS DISTINCT FROM '36c298d2d3152ae660bb7b6b3fee01c92f7e770f1b0e6f8aa025d12b666f6d33'
  OR EXISTS(SELECT 1 FROM private_custody_inventory_before WHERE definition_sha256 IS DISTINCT FROM public.static_weekly_digest_text(definition_sql))
 THEN RAISE EXCEPTION 'Private custody exact source252 recovery predecessor changed';END IF;
 SELECT * INTO STRICT saved FROM private_custody_inventory_before WHERE object_kind='function' AND object_identity LIKE '%(%'
  AND to_regprocedure(object_identity)='public.custodial_release_canary_authority_surface()'::regprocedure;
 IF saved.definition_sql IS DISTINCT FROM body OR saved.definition_sha256 IS DISTINCT FROM public.static_weekly_digest_text(body)
  OR NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.custodial_release_authority_restore_inventory'::regclass
   AND tgname='trg_custodial_release_authority_restore_inventory_immutable' AND tgenabled='A')
  OR to_regclass('public.custodial_native_private_custody_operations') IS NOT NULL
  OR to_regclass('public.custodial_native_private_custody_chunks') IS NOT NULL
  OR EXISTS(SELECT 1 FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN(
   'custodial_private_custody_v1_immutable','custodial_private_custody_v1_retain_chunk','custodial_private_custody_v1_read_chunk'))
 THEN RAISE EXCEPTION 'Private custody predecessor guard changed or unadmitted survivors exist';END IF;
END $private_predecessor$;

CREATE TABLE public.custodial_native_private_custody_operations (
 operation_id uuid PRIMARY KEY,
 separation_id uuid NOT NULL REFERENCES public.custodial_employee_separation_fences(separation_id),
 generation_id uuid NOT NULL REFERENCES public.employee_native_push_generations(generation_id),
 device_id uuid NOT NULL REFERENCES public.devices(id),
 credential_id uuid NOT NULL REFERENCES public.device_auth_credentials(credential_id),
 original_context jsonb NOT NULL CHECK(jsonb_typeof(original_context)='object'),
 original_generation jsonb NOT NULL CHECK(jsonb_typeof(original_generation)='object'),
 verified_binding jsonb NOT NULL CHECK(jsonb_typeof(verified_binding)='object'),
 owner_proof jsonb NOT NULL CHECK(jsonb_typeof(owner_proof)='object'),
 original_wire bytea NOT NULL CHECK(octet_length(original_wire) BETWEEN 1 AND 262144),
 original_wire_sha256 text NOT NULL CHECK(original_wire_sha256 ~ '^[0-9a-f]{64}$'),
 principal_digest text NOT NULL CHECK(principal_digest ~ '^[0-9a-f]{64}$'),
 plan_sha256 text NOT NULL CHECK(plan_sha256 ~ '^[0-9a-f]{64}$'),
 frame_sha256 text NOT NULL CHECK(frame_sha256 ~ '^[0-9a-f]{64}$'),
 record_sha256 text NOT NULL CHECK(record_sha256 ~ '^[0-9a-f]{64}$'),
 frame_bytes integer NOT NULL CHECK(frame_bytes BETWEEN 1 AND 42500000),
 chunk_count integer NOT NULL CHECK(chunk_count=(frame_bytes+24575)/24576),
 retained_at timestamptz NOT NULL DEFAULT clock_timestamp() CHECK(isfinite(retained_at)),
 CHECK(original_wire_sha256=encode(extensions.digest(original_wire,'sha256'),'hex'))
);
CREATE TABLE public.custodial_native_private_custody_chunks (
 operation_id uuid NOT NULL REFERENCES public.custodial_native_private_custody_operations(operation_id),
 chunk_index integer NOT NULL CHECK(chunk_index>=0),
 write_id uuid NOT NULL UNIQUE,
 native_request_id uuid NOT NULL UNIQUE,
 chunk_bytes bytea NOT NULL CHECK(octet_length(chunk_bytes) BETWEEN 1 AND 24576),
 chunk_sha256 text NOT NULL CHECK(chunk_sha256 ~ '^[0-9a-f]{64}$'),
 request_bytes bytea NOT NULL CHECK(octet_length(request_bytes) BETWEEN 1 AND 393216),
 request_body_sha256 text NOT NULL CHECK(request_body_sha256 ~ '^[0-9a-f]{64}$'),
 attestation_digest text NOT NULL CHECK(attestation_digest ~ '^[0-9a-f]{64}$'),
 received_at timestamptz NOT NULL DEFAULT clock_timestamp() CHECK(isfinite(received_at)),
 PRIMARY KEY(operation_id,chunk_index),
 CHECK(chunk_sha256=encode(extensions.digest(chunk_bytes,'sha256'),'hex')),
 CHECK(request_body_sha256=encode(extensions.digest(request_bytes,'sha256'),'hex'))
);
CREATE INDEX custodial_native_private_custody_operation_owner_idx ON public.custodial_native_private_custody_operations(device_id,credential_id,generation_id);
CREATE INDEX custodial_native_private_custody_operation_separation_idx ON public.custodial_native_private_custody_operations(separation_id);
CREATE INDEX custodial_native_private_custody_operation_generation_idx ON public.custodial_native_private_custody_operations(generation_id);
CREATE INDEX custodial_native_private_custody_operation_credential_idx ON public.custodial_native_private_custody_operations(credential_id);
ALTER TABLE public.custodial_native_private_custody_operations ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.custodial_native_private_custody_operations FORCE ROW LEVEL SECURITY;
ALTER TABLE public.custodial_native_private_custody_chunks ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.custodial_native_private_custody_chunks FORCE ROW LEVEL SECURITY;
REVOKE ALL ON public.custodial_native_private_custody_operations,public.custodial_native_private_custody_chunks
 FROM PUBLIC,anon,authenticated,service_role,custodial_application_reader,static_weekly_control_plane,static_weekly_release_operator;
CREATE FUNCTION public.custodial_private_custody_v1_immutable()
RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $fn$
BEGIN RAISE EXCEPTION USING errcode='42501',message='original opaque custody evidence is immutable';END $fn$;
REVOKE ALL ON FUNCTION public.custodial_private_custody_v1_immutable()
 FROM PUBLIC,anon,authenticated,service_role,custodial_application_reader,static_weekly_control_plane,static_weekly_release_operator;
CREATE TRIGGER trg_native_private_custody_operation_immutable BEFORE UPDATE OR DELETE ON public.custodial_native_private_custody_operations
 FOR EACH ROW EXECUTE FUNCTION public.custodial_private_custody_v1_immutable();
CREATE TRIGGER trg_native_private_custody_chunk_immutable BEFORE UPDATE OR DELETE ON public.custodial_native_private_custody_chunks
 FOR EACH ROW EXECUTE FUNCTION public.custodial_private_custody_v1_immutable();
CREATE TRIGGER trg_native_private_custody_operation_no_truncate BEFORE TRUNCATE ON public.custodial_native_private_custody_operations
 FOR EACH STATEMENT EXECUTE FUNCTION public.custodial_private_custody_v1_immutable();
CREATE TRIGGER trg_native_private_custody_chunk_no_truncate BEFORE TRUNCATE ON public.custodial_native_private_custody_chunks
 FOR EACH STATEMENT EXECUTE FUNCTION public.custodial_private_custody_v1_immutable();
ALTER TABLE public.custodial_native_private_custody_operations ENABLE ALWAYS TRIGGER trg_native_private_custody_operation_immutable;
ALTER TABLE public.custodial_native_private_custody_chunks ENABLE ALWAYS TRIGGER trg_native_private_custody_chunk_immutable;
ALTER TABLE public.custodial_native_private_custody_operations ENABLE ALWAYS TRIGGER trg_native_private_custody_operation_no_truncate;
ALTER TABLE public.custodial_native_private_custody_chunks ENABLE ALWAYS TRIGGER trg_native_private_custody_chunk_no_truncate;
-- Existing common disaster-restore DDL hook must attach its normal mutation
-- fence to BOTH new relations. A missing/changed hook is not repaired here by
-- an ad-hoc grant, disabled guard or substitute privileged application path.
DO $mutation_boundary$ BEGIN
 IF (SELECT count(*) FROM pg_trigger WHERE tgrelid IN(
   'public.custodial_native_private_custody_operations'::regclass,'public.custodial_native_private_custody_chunks'::regclass)
   AND tgname='custodial_disaster_restore_mutation_fence'
   AND tgfoid='custodial_dr.guard_application_mutation()'::regprocedure AND tgenabled='O' AND NOT tgisinternal)<>2
 THEN RAISE EXCEPTION 'Private custody existing disaster-restore mutation boundary unavailable';END IF;
END $mutation_boundary$;

-- Genuinely owner-privileged internal access follows the existing native
-- separation RPC boundary; no JWT user_metadata or employee/browser table grant.
CREATE FUNCTION public.custodial_private_custody_v1_retain_chunk(
 p_operation uuid,p_device uuid,p_credential uuid,p_credential_hash text,p_credential_key_id text,p_generation uuid,
 p_native_request uuid,p_attestation_digest text,p_request_base64 text,p_binding jsonb,p_owner_proof jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $fn$
DECLARE credential public.device_auth_credentials%rowtype;context jsonb;generation jsonb;frame jsonb;
 request_bytes bytea;wire bytea;chunk bytea;request_sha text;wire_sha text;frame_length integer;chunks integer;idx integer;
 prior public.custodial_native_private_custody_operations%rowtype;existing public.custodial_native_private_custody_chunks%rowtype;
 replayed boolean:=false;key text;keys text[];wire_json jsonb;manifest jsonb;
BEGIN
 IF p_operation IS NULL OR p_device IS NULL OR p_credential IS NULL OR p_generation IS NULL OR p_native_request IS NULL
  OR p_credential_hash IS NULL OR p_credential_hash !~ '^[0-9a-f]{64}$' OR p_credential_key_id IS NULL OR p_credential_key_id !~ '^[0-9a-f]{64}$'
  OR p_attestation_digest IS NULL OR p_attestation_digest !~ '^[0-9a-f]{64}$' OR p_request_base64 IS NULL OR length(p_request_base64)>524288
  OR p_request_base64 !~ '^[A-Za-z0-9+/]+={0,2}$' OR jsonb_typeof(p_binding) IS DISTINCT FROM 'object' OR jsonb_typeof(p_owner_proof) IS DISTINCT FROM 'object'
 THEN RAISE EXCEPTION USING errcode='22023',message='closed original private custody request required';END IF;
 SELECT array_agg(k ORDER BY k COLLATE "C") INTO keys FROM jsonb_object_keys(p_binding) k;
 IF keys IS DISTINCT FROM ARRAY['automatic_acceptance','browser_inventory_state','credential_id','generation_activated_at','generation_id','inventory_acknowledged','manifest_sha256','native_semantic_inventory_state','new_work_allowed','phone_released','principal_digest','raw_snapshot_sha256','record_count','schema','separation_id','verification']::text[]
  OR p_binding->>'schema' IS DISTINCT FROM 'custodial.native-protected-generation-raw-binding.v1'
  OR p_binding->>'verification' IS DISTINCT FROM 'MATCHED_PRE_CUTOFF_GENERATION_RAW_BINDING_RETENTION_ONLY'
  OR p_binding->>'native_semantic_inventory_state' IS DISTINCT FROM 'UNKNOWN' OR p_binding->>'browser_inventory_state' IS DISTINCT FROM 'UNKNOWN'
  OR p_binding->'automatic_acceptance' IS DISTINCT FROM 'false'::jsonb
 THEN RAISE EXCEPTION USING errcode='22023',message='closed identity-only generation binding required';END IF;
 request_bytes:=decode(p_request_base64,'base64');IF octet_length(request_bytes) NOT BETWEEN 1 AND 393216
  OR replace(encode(request_bytes,'base64'),E'\n','') IS DISTINCT FROM p_request_base64 THEN RAISE EXCEPTION USING errcode='22023',message='exact request bytes required';END IF;
 -- Existing strict duplicate/UTF8/bounded native JSON validator, unchanged.
 PERFORM public.custodial_v15_assert_native_json(convert_from(request_bytes,'UTF8')::json,0);
 frame:=convert_from(request_bytes,'UTF8')::jsonb;
 SELECT array_agg(k ORDER BY k COLLATE "C") INTO keys FROM jsonb_object_keys(frame) k;
 IF keys IS DISTINCT FROM ARRAY['attempt_id','chunk_base64','chunk_bytes','chunk_count','chunk_index','chunk_sha256','engine_revision','frame_bytes','frame_sha256','offset','operation_id','original_frozen_work_sha256','original_generation_id','original_signed_wire_base64','owner_proof_base64','plan_sha256','principal_digest','purpose_attestation','purpose_binding_sha256','read_query_id','record_sha256','schema','write_id']::text[]
 THEN RAISE EXCEPTION USING errcode='22023',message='exact private write envelope fields required';END IF;
 FOR key IN SELECT jsonb_object_keys(frame) LOOP IF jsonb_typeof(frame->key) IS DISTINCT FROM 'string' THEN RAISE EXCEPTION USING errcode='22023',message='private write literal strings required';END IF;END LOOP;
 IF frame->>'schema' IS DISTINCT FROM 'custodial.original-native-private-custody-write.v1'
  OR frame->>'operation_id' IS DISTINCT FROM p_operation::text OR frame->>'original_generation_id' IS DISTINCT FROM p_generation::text
  OR frame->>'attempt_id' IS DISTINCT FROM p_native_request::text OR p_binding->>'credential_id' IS DISTINCT FROM p_credential::text
  OR p_binding->>'generation_id' IS DISTINCT FROM p_generation::text OR p_binding->>'principal_digest' IS DISTINCT FROM frame->>'principal_digest'
  OR p_owner_proof->>'credential_id' IS DISTINCT FROM p_credential::text OR p_owner_proof->>'original_generation_id' IS DISTINCT FROM p_generation::text
  OR p_owner_proof->>'principal_digest' IS DISTINCT FROM frame->>'principal_digest' OR p_owner_proof->>'record_sha256' IS DISTINCT FROM frame->>'record_sha256'
  OR p_binding->'new_work_allowed' IS DISTINCT FROM 'false'::jsonb OR p_binding->'phone_released' IS DISTINCT FROM 'false'::jsonb
  OR p_binding->'inventory_acknowledged' IS DISTINCT FROM 'false'::jsonb THEN RAISE EXCEPTION USING errcode='22023',message='original identity-only scope required';END IF;
 FOREACH key IN ARRAY ARRAY['frame_sha256','record_sha256','plan_sha256','chunk_sha256','principal_digest'] LOOP
  IF frame->>key IS NULL OR frame->>key !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION USING errcode='22023',message='exact private custody digest required';END IF;
 END LOOP;
 FOREACH key IN ARRAY ARRAY['frame_bytes','chunk_count','chunk_index','offset','chunk_bytes'] LOOP
  IF frame->>key IS NULL OR frame->>key !~ '^(0|[1-9][0-9]*)$' OR length(frame->>key)>8 THEN RAISE EXCEPTION USING errcode='22023',message='bounded chunk shape required';END IF;
 END LOOP;
 frame_length:=(frame->>'frame_bytes')::integer;chunks:=(frame->>'chunk_count')::integer;idx:=(frame->>'chunk_index')::integer;
 IF frame_length NOT BETWEEN 1 AND 42500000 OR chunks<>(frame_length+24575)/24576 OR idx<0 OR idx>=chunks OR (frame->>'offset')::integer<>idx*24576 THEN RAISE EXCEPTION USING errcode='22023',message='exact chunk offset/count required';END IF;
 wire:=decode(frame->>'original_signed_wire_base64','base64');chunk:=decode(frame->>'chunk_base64','base64');
 IF octet_length(wire) NOT BETWEEN 1 AND 262144 OR replace(encode(wire,'base64'),E'\n','') IS DISTINCT FROM frame->>'original_signed_wire_base64'
  OR octet_length(chunk)<>least(24576,frame_length-idx*24576) OR octet_length(chunk)<>(frame->>'chunk_bytes')::integer
  OR replace(encode(chunk,'base64'),E'\n','') IS DISTINCT FROM frame->>'chunk_base64'
  OR encode(extensions.digest(chunk,'sha256'),'hex') IS DISTINCT FROM frame->>'chunk_sha256' THEN RAISE EXCEPTION USING errcode='22023',message='exact original encrypted slice required';END IF;
 wire_sha:=encode(extensions.digest(wire,'sha256'),'hex');request_sha:=encode(extensions.digest(request_bytes,'sha256'),'hex');
 IF p_owner_proof->>'original_wire_sha256' IS DISTINCT FROM wire_sha THEN RAISE EXCEPTION USING errcode='22023',message='original signed identity wire required';END IF;
 PERFORM public.custodial_v15_assert_native_json(convert_from(wire,'UTF8')::json,0);wire_json:=convert_from(wire,'UTF8')::jsonb;
 IF wire_json->>'manifest_sha256' IS DISTINCT FROM p_binding->>'manifest_sha256' OR jsonb_typeof(wire_json->'manifest_body') IS DISTINCT FROM 'string'
  OR encode(extensions.digest(convert_to(wire_json->>'manifest_body','UTF8'),'sha256'),'hex') IS DISTINCT FROM p_binding->>'manifest_sha256'
 THEN RAISE EXCEPTION USING errcode='22023',message='original manifest identity required';END IF;
 PERFORM public.custodial_v15_assert_native_json((wire_json->>'manifest_body')::json,0);manifest:=(wire_json->>'manifest_body')::jsonb;
 IF manifest->>'raw_snapshot_sha256' IS DISTINCT FROM p_binding->>'raw_snapshot_sha256' OR manifest->'record_count' IS DISTINCT FROM p_binding->'record_count'
 THEN RAISE EXCEPTION USING errcode='22023',message='original snapshot identity required';END IF;
 PERFORM public.custodial_begin_application_mutation();
 PERFORM pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 SELECT * INTO credential FROM public.device_auth_credentials WHERE credential_id=p_credential AND device_id=p_device FOR SHARE;
 IF NOT FOUND OR credential.revoked_at IS NOT NULL OR credential.confirmed_at IS NULL OR credential.token_hash IS DISTINCT FROM p_credential_hash
  OR credential.metadata_json IS NOT NULL AND jsonb_typeof(credential.metadata_json) NOT IN ('object','null')
  OR jsonb_typeof(credential.metadata_json)='object' AND credential.metadata_json ? 'credential_secret_key_id'
   AND (jsonb_typeof(credential.metadata_json->'credential_secret_key_id') IS DISTINCT FROM 'string' OR credential.metadata_json->>'credential_secret_key_id' IS DISTINCT FROM p_credential_key_id)
 THEN RAISE EXCEPTION USING errcode='42501',message='current original credential required at custody transaction';END IF;
 context:=public.custodial_v13_read_separation_context(p_device,p_credential);
 IF context IS NULL OR context->>'separation_id' IS DISTINCT FROM p_binding->>'separation_id' OR context->>'state' IS DISTINCT FROM 'PENDING_RECONCILIATION'
 THEN RAISE EXCEPTION USING errcode='42501',message='current original separation required';END IF;
 IF manifest#>>'{original_principal,device_id}' IS DISTINCT FROM context->>'canonical_device_id' OR manifest#>>'{original_principal,employee_id}' IS DISTINCT FROM context->>'employee_id'
  OR manifest#>>'{original_principal,credential_id}' IS DISTINCT FROM context->>'credential_id' OR manifest#>'{original_principal,assignment_epoch}' IS DISTINCT FROM context->'assignment_epoch'
 THEN RAISE EXCEPTION USING errcode='42501',message='original full principal tuple required';END IF;
 PERFORM 1 FROM public.custodial_employee_separation_fences WHERE separation_id=(context->>'separation_id')::uuid FOR UPDATE;
 generation:=public.custodial_v14_read_separation_generation(p_device,p_credential,(context->>'separation_id')::uuid,p_generation,frame->>'principal_digest');
 IF generation IS NULL OR generation->>'activated_at' IS DISTINCT FROM p_binding->>'generation_activated_at' THEN RAISE EXCEPTION USING errcode='42501',message='current original generation required';END IF;
 SELECT * INTO prior FROM public.custodial_native_private_custody_operations WHERE operation_id=p_operation;
 IF FOUND THEN
  IF prior.device_id<>p_device OR prior.credential_id<>p_credential OR prior.generation_id<>p_generation OR prior.separation_id<>(context->>'separation_id')::uuid
   OR prior.frame_sha256 IS DISTINCT FROM frame->>'frame_sha256' OR prior.record_sha256 IS DISTINCT FROM frame->>'record_sha256' OR prior.plan_sha256 IS DISTINCT FROM frame->>'plan_sha256'
   OR prior.original_wire IS DISTINCT FROM wire OR prior.owner_proof IS DISTINCT FROM p_owner_proof OR prior.verified_binding IS DISTINCT FROM p_binding
   OR prior.frame_bytes<>frame_length OR prior.chunk_count<>chunks THEN RAISE EXCEPTION USING errcode='23505',message='original private custody operation conflict';END IF;
 ELSE
  INSERT INTO public.custodial_native_private_custody_operations(operation_id,separation_id,generation_id,device_id,credential_id,original_context,original_generation,verified_binding,owner_proof,original_wire,original_wire_sha256,principal_digest,plan_sha256,frame_sha256,record_sha256,frame_bytes,chunk_count)
   VALUES(p_operation,(context->>'separation_id')::uuid,p_generation,p_device,p_credential,context,generation,p_binding,p_owner_proof,wire,wire_sha,frame->>'principal_digest',frame->>'plan_sha256',frame->>'frame_sha256',frame->>'record_sha256',frame_length,chunks) RETURNING * INTO prior;
 END IF;
 SELECT * INTO existing FROM public.custodial_native_private_custody_chunks WHERE operation_id=p_operation AND chunk_index=idx;
 IF FOUND THEN
  IF existing.write_id<>(frame->>'write_id')::uuid OR existing.native_request_id<>p_native_request OR existing.chunk_bytes IS DISTINCT FROM chunk
   OR existing.request_bytes IS DISTINCT FROM request_bytes OR existing.attestation_digest IS DISTINCT FROM p_attestation_digest THEN RAISE EXCEPTION USING errcode='23505',message='original private custody chunk/request conflict';END IF;replayed:=true;
 ELSE
  INSERT INTO public.custodial_native_private_custody_chunks(operation_id,chunk_index,write_id,native_request_id,chunk_bytes,chunk_sha256,request_bytes,request_body_sha256,attestation_digest)
   VALUES(p_operation,idx,(frame->>'write_id')::uuid,p_native_request,chunk,frame->>'chunk_sha256',request_bytes,request_sha,p_attestation_digest) RETURNING * INTO existing;
 END IF;
 RETURN jsonb_build_object('schema','custodial.private-custody-chunk-receipt.v1','state','OPAQUE_CHUNK_RETAINED_ONLY_PENDING_RECONCILIATION',
  'operation_id',p_operation,'generation_id',p_generation,'chunk_index',idx,'native_request_id',p_native_request,'request_body_sha256',request_sha,'attestation_digest',p_attestation_digest,
  'frame_sha256',prior.frame_sha256,'plan_sha256',prior.plan_sha256,'chunk_sha256',existing.chunk_sha256,'replayed',replayed,
  'inventory_acknowledged',false,'work_accepted',false,'new_work_allowed',false,'resend_allowed',false,'finalizer_allowed',false,'key_removal',false,'phone_released',false);
END $fn$;
REVOKE ALL ON FUNCTION public.custodial_private_custody_v1_retain_chunk(uuid,uuid,uuid,text,text,uuid,uuid,text,text,jsonb,jsonb)
 FROM PUBLIC,anon,authenticated,service_role,custodial_application_reader,static_weekly_control_plane,static_weekly_release_operator;
GRANT EXECUTE ON FUNCTION public.custodial_private_custody_v1_retain_chunk(uuid,uuid,uuid,text,text,uuid,uuid,text,text,jsonb,jsonb) TO service_role;

CREATE FUNCTION public.custodial_private_custody_v1_read_chunk(
 p_operation uuid,p_device uuid,p_credential uuid,p_credential_hash text,p_credential_key_id text,p_generation uuid,p_chunk_index integer,p_native_request uuid,p_request_sha256 text,p_attestation_digest text)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $fn$
DECLARE credential public.device_auth_credentials%rowtype;op public.custodial_native_private_custody_operations%rowtype;chunk public.custodial_native_private_custody_chunks%rowtype;context jsonb;generation jsonb;
BEGIN
 IF p_operation IS NULL OR p_device IS NULL OR p_credential IS NULL OR p_generation IS NULL OR p_chunk_index IS NULL OR p_chunk_index<0 OR p_native_request IS NULL
  OR p_credential_hash IS NULL OR p_credential_hash !~ '^[0-9a-f]{64}$' OR p_credential_key_id IS NULL OR p_credential_key_id !~ '^[0-9a-f]{64}$'
  OR p_request_sha256 IS NULL OR p_request_sha256 !~ '^[0-9a-f]{64}$' OR p_attestation_digest IS NULL OR p_attestation_digest !~ '^[0-9a-f]{64}$'
 THEN RAISE EXCEPTION USING errcode='22023',message='exact original private custody read target required';END IF;
 SELECT * INTO credential FROM public.device_auth_credentials WHERE credential_id=p_credential AND device_id=p_device;
 IF NOT FOUND OR credential.revoked_at IS NOT NULL OR credential.confirmed_at IS NULL OR credential.token_hash IS DISTINCT FROM p_credential_hash
  OR credential.metadata_json IS NOT NULL AND jsonb_typeof(credential.metadata_json) NOT IN ('object','null')
  OR jsonb_typeof(credential.metadata_json)='object' AND credential.metadata_json ? 'credential_secret_key_id'
   AND (jsonb_typeof(credential.metadata_json->'credential_secret_key_id') IS DISTINCT FROM 'string' OR credential.metadata_json->>'credential_secret_key_id' IS DISTINCT FROM p_credential_key_id)
 THEN RAISE EXCEPTION USING errcode='42501',message='current private custody read credential required';END IF;
 SELECT * INTO op FROM public.custodial_native_private_custody_operations WHERE operation_id=p_operation AND device_id=p_device AND credential_id=p_credential AND generation_id=p_generation;
 IF NOT FOUND THEN RETURN NULL;END IF;
 context:=public.custodial_v13_read_separation_context(p_device,p_credential);
 IF context IS NULL OR context->>'separation_id' IS DISTINCT FROM op.separation_id::text THEN RAISE EXCEPTION USING errcode='42501',message='current private custody read separation required';END IF;
 generation:=public.custodial_v14_read_separation_generation(p_device,p_credential,op.separation_id,p_generation,op.principal_digest);
 IF generation IS NULL OR generation IS DISTINCT FROM op.original_generation THEN RAISE EXCEPTION USING errcode='42501',message='original private custody read generation required';END IF;
 SELECT * INTO chunk FROM public.custodial_native_private_custody_chunks WHERE operation_id=p_operation AND chunk_index=p_chunk_index AND native_request_id=p_native_request;
 IF NOT FOUND THEN RETURN NULL;END IF;
 IF chunk.request_body_sha256 IS DISTINCT FROM p_request_sha256 OR chunk.attestation_digest IS DISTINCT FROM p_attestation_digest
  OR chunk.request_body_sha256 IS DISTINCT FROM encode(extensions.digest(chunk.request_bytes,'sha256'),'hex') OR chunk.chunk_sha256 IS DISTINCT FROM encode(extensions.digest(chunk.chunk_bytes,'sha256'),'hex')
 THEN RAISE EXCEPTION USING errcode='23514',message='original private custody read witness mismatch';END IF;
 RETURN jsonb_build_object('schema','custodial.private-custody-chunk-readback.v1','state','OPAQUE_CHUNK_READ_ONLY_PENDING_RECONCILIATION','operation_id',p_operation,'generation_id',p_generation,
  'chunk_index',p_chunk_index,'native_request_id',p_native_request,'request_body_sha256',p_request_sha256,'attestation_digest',p_attestation_digest,'frame_sha256',op.frame_sha256,'record_sha256',op.record_sha256,
  'plan_sha256',op.plan_sha256,'chunk_sha256',chunk.chunk_sha256,'chunk_bytes',octet_length(chunk.chunk_bytes),
  'received_at',to_char(chunk.received_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
  'frame_complete_syntax_verified',false,'inventory_acknowledged',false,'work_accepted',false,'new_work_allowed',false,'resend_allowed',false,'finalizer_allowed',false,'key_removal',false,'phone_released',false);
END $fn$;
REVOKE ALL ON FUNCTION public.custodial_private_custody_v1_read_chunk(uuid,uuid,uuid,text,text,uuid,integer,uuid,text,text)
 FROM PUBLIC,anon,authenticated,service_role,custodial_application_reader,static_weekly_control_plane,static_weekly_release_operator;
GRANT EXECUTE ON FUNCTION public.custodial_private_custody_v1_read_chunk(uuid,uuid,uuid,text,text,uuid,integer,uuid,text,text) TO service_role,custodial_application_reader;

-- Exact recovery/canary inventory extension is intentionally still a draft
-- qualification requirement; the finite source extension below is NOT live
-- admission, production fingerprint, full restore or operational acceptance.
CREATE TEMP TABLE private_custody_objects ON COMMIT DROP AS
 WITH funcs AS(SELECT p.oid FROM pg_proc p WHERE p.pronamespace='public'::regnamespace AND p.proname IN(
  'custodial_private_custody_v1_immutable','custodial_private_custody_v1_retain_chunk','custodial_private_custody_v1_read_chunk')),
 objects AS(
 SELECT 100000 bucket,0 priority,'function'::text kind,'public.'||oid::regprocedure::text identity,pg_get_functiondef(oid) definition FROM funcs
 UNION ALL SELECT 900000,0,'grant','public.'||oid::regprocedure::text,public.custodial_release_authority_current_grant_definition('public.'||oid::regprocedure::text) FROM funcs
 UNION ALL SELECT x.bucket,x.priority,x.kind,x.identity,x.definition FROM unnest(array[
  'public.custodial_native_private_custody_operations','public.custodial_native_private_custody_chunks']) rel CROSS JOIN LATERAL(
  SELECT 1000 bucket,0 priority,'relation'::text kind,rel identity,public.custodial_release_authority_current_relation_definition(rel) definition
  UNION ALL SELECT 200000,0,'column',rel||':'||attname,public.custodial_release_authority_current_column_definition(rel||':'||attname)
   FROM pg_attribute WHERE attrelid=rel::regclass AND attnum>0 AND NOT attisdropped
  UNION ALL SELECT 300000,0,'column_set',rel,public.custodial_release_authority_current_column_set_definition(rel)
  UNION ALL SELECT 400000,0,'relation_state',rel,public.custodial_release_authority_current_relation_state_definition(rel)
  UNION ALL SELECT 500000,CASE WHEN contype='f' THEN 1 ELSE 0 END,'constraint',rel||':'||conname,public.custodial_release_authority_current_constraint_definition(rel||':'||conname)
   FROM pg_constraint WHERE conrelid=rel::regclass
  UNION ALL SELECT 600000,0,'index',indexrelid::regclass::text,public.custodial_release_authority_current_index_definition(indexrelid::regclass::text)
   FROM pg_index i WHERE indrelid=rel::regclass AND NOT EXISTS(SELECT 1 FROM pg_constraint c WHERE c.conindid=i.indexrelid)
  UNION ALL SELECT 700000,0,'trigger',rel||'.'||tgname,'drop trigger if exists '||quote_ident(tgname)||' on '||rel||'; '
   ||pg_get_triggerdef(oid,true)||'; alter table '||rel||CASE WHEN tgenabled='A' THEN ' enable always trigger ' ELSE ' enable trigger ' END||quote_ident(tgname)||';'
   FROM pg_trigger WHERE tgrelid=rel::regclass AND NOT tgisinternal
  UNION ALL SELECT 800000,0,'policy',rel||':'||polname,public.custodial_release_authority_current_policy_definition(rel||':'||polname)
   FROM pg_policy WHERE polrelid=rel::regclass
  UNION ALL SELECT 900000,0,'grant',rel,public.custodial_release_authority_current_grant_definition(rel)) x)
 SELECT * FROM objects;
DO $private_objects$ BEGIN
 IF (SELECT count(*) FROM private_custody_objects)<>84
  OR (SELECT count(*) FROM private_custody_objects WHERE kind='function')<>3
  OR (SELECT count(*) FROM private_custody_objects WHERE kind='relation')<>2
  OR (SELECT count(*) FROM private_custody_objects WHERE kind='column')<>28
  OR (SELECT count(*) FROM private_custody_objects WHERE kind='column_set')<>2
  OR (SELECT count(*) FROM private_custody_objects WHERE kind='relation_state')<>2
  OR (SELECT count(*) FROM private_custody_objects WHERE kind='constraint')<>32
  OR (SELECT count(*) FROM private_custody_objects WHERE kind='index')<>4
  OR (SELECT count(*) FROM private_custody_objects WHERE kind='trigger')<>6
  OR (SELECT count(*) FROM private_custody_objects WHERE kind='policy')<>0
  OR (SELECT count(*) FROM private_custody_objects WHERE kind='grant')<>5
  OR EXISTS(SELECT 1 FROM private_custody_objects WHERE definition IS NULL)
  OR EXISTS(SELECT kind,identity FROM private_custody_objects GROUP BY kind,identity HAVING count(*)<>1)
  OR EXISTS(SELECT 1 FROM private_custody_inventory_before old JOIN private_custody_objects x ON x.kind=old.object_kind AND x.identity=old.object_identity)
 THEN RAISE EXCEPTION 'Private custody finite source object declaration changed';END IF;
END $private_objects$;
DO $private_surface$ DECLARE original text;patched text;entries text;BEGIN
 SELECT definition INTO STRICT original FROM private_custody_surface_before;
 SELECT string_agg('('||quote_literal(kind)||','||quote_literal(identity)||','||quote_literal('opaque original private custody only; no namespace semantics, ACK, work, resend, finalizer or key/reuse authority')||'),',E'\n' ORDER BY kind,identity)
  INTO entries FROM private_custody_objects;
 patched:=replace(original,'  values','  values'||E'\n'||entries);EXECUTE patched;
 IF pg_get_functiondef('public.custodial_release_canary_authority_surface()'::regprocedure) IS DISTINCT FROM patched
  OR (SELECT proacl FROM pg_proc WHERE oid='public.custodial_release_canary_authority_surface()'::regprocedure)
   IS DISTINCT FROM (SELECT acl FROM private_custody_surface_before)
  OR (SELECT proowner FROM pg_proc WHERE oid='public.custodial_release_canary_authority_surface()'::regprocedure)
   IS DISTINCT FROM (SELECT owner FROM private_custody_surface_before)
 THEN RAISE EXCEPTION 'Private custody canary owner/ACL/body changed outside exact finite extension';END IF;
END $private_surface$;
-- Same normal, exclusive-lock, exact-predecessor inventory extension used by
-- the existing source251/252 migration controls. No application guard is changed.
ALTER TABLE public.custodial_release_authority_restore_inventory DISABLE TRIGGER trg_custodial_release_authority_restore_inventory_immutable;
DO $private_recovery$ DECLARE obj record;next_order integer;changed integer;BEGIN
 UPDATE public.custodial_release_authority_restore_inventory SET
  definition_sql=pg_get_functiondef('public.custodial_release_canary_authority_surface()'::regprocedure),
  definition_sha256=public.static_weekly_digest_text(pg_get_functiondef('public.custodial_release_canary_authority_surface()'::regprocedure)),captured_at=statement_timestamp()
  WHERE object_kind='function' AND object_identity LIKE '%(%'
   AND to_regprocedure(object_identity)='public.custodial_release_canary_authority_surface()'::regprocedure
   AND definition_sql=(SELECT definition FROM private_custody_surface_before);
 GET DIAGNOSTICS changed=ROW_COUNT;IF changed<>1 THEN RAISE EXCEPTION 'Private custody exact canary inventory predecessor changed';END IF;
 FOR obj IN SELECT * FROM private_custody_objects ORDER BY bucket,priority,identity LOOP
  SELECT n INTO next_order FROM generate_series(obj.bucket+1,CASE WHEN obj.bucket=1000 THEN 99998 ELSE obj.bucket+99998 END) n
   WHERE NOT EXISTS(SELECT 1 FROM public.custodial_release_authority_restore_inventory WHERE restore_order=n) ORDER BY n LIMIT 1;
  IF next_order IS NULL THEN RAISE EXCEPTION 'Private custody finite recovery order exhausted';END IF;
  INSERT INTO public.custodial_release_authority_restore_inventory(restore_order,object_kind,object_identity,definition_sql,definition_sha256)
   VALUES(next_order,obj.kind,obj.identity,obj.definition,public.static_weekly_digest_text(obj.definition));
 END LOOP;
END $private_recovery$;
ALTER TABLE public.custodial_release_authority_restore_inventory ENABLE ALWAYS TRIGGER trg_custodial_release_authority_restore_inventory_immutable;
DO $private_scope$ BEGIN
 IF (SELECT count(*) FROM public.custodial_release_authority_restore_inventory)<>6968
  OR EXISTS(SELECT old.* FROM private_custody_inventory_before old WHERE NOT(object_kind='function' AND object_identity LIKE '%(%'
   AND to_regprocedure(object_identity)='public.custodial_release_canary_authority_surface()'::regprocedure)
   EXCEPT SELECT * FROM public.custodial_release_authority_restore_inventory)
  OR EXISTS(SELECT now.* FROM public.custodial_release_authority_restore_inventory now WHERE NOT(object_kind='function' AND object_identity LIKE '%(%'
   AND to_regprocedure(object_identity)='public.custodial_release_canary_authority_surface()'::regprocedure)
   AND NOT EXISTS(SELECT 1 FROM private_custody_objects x WHERE x.kind=now.object_kind AND x.identity=now.object_identity)
   EXCEPT SELECT * FROM private_custody_inventory_before)
  OR EXISTS(SELECT 1 FROM private_custody_objects x LEFT JOIN public.custodial_release_authority_restore_inventory i
   ON x.kind=i.object_kind AND x.identity=i.object_identity WHERE i.definition_sql IS DISTINCT FROM x.definition
    OR i.definition_sha256 IS DISTINCT FROM public.static_weekly_digest_text(x.definition))
  OR NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.custodial_release_authority_restore_inventory'::regclass
   AND tgname='trg_custodial_release_authority_restore_inventory_immutable' AND tgenabled='A')
 THEN RAISE EXCEPTION 'Private custody unrelated recovery scope, exact new bytes or final ALWAYS inventory guard changed';END IF;
END $private_scope$;
COMMIT;
